    fx.flash(t2.clone().add(new THREE.Vector3(0, .4, 0)), 0xffd090, .5, 2.6, .3);
    audio.play('boom');
    for (const e of enemies) {
      if (!e.alive) continue;
      if (e.pos(true).distanceTo(t2) <= 2.4) { const d = e.takeHit(100); if (d) ctxHit(null, e, d); }
