// Shadowspire Ninja — procedural canvas art. Every visible mark is drawn here:
// indigo washi sky, cut-paper tower, copper/timber/stone ledges, lantern dust,
// warning caltrops and a hand-inked ninja with eight metres of scarf.

import { CFG, zoneAt } from './level.js';

const W = CFG.W, H = CFG.H, PPM = CFG.PPM;
const TAU = Math.PI * 2;

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makePaper() {
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d');
  const r = rng(0x9A17C0DE);
  g.clearRect(0, 0, W, H);
  for (let i = 0; i < 4200; i++) {
    const x = r() * W, y = r() * H;
    g.fillStyle = r() < 0.68 ? `rgba(255,232,196,${0.012 + r() * 0.025})` : `rgba(0,0,0,${0.01 + r() * 0.035})`;
    g.fillRect(x, y, r() < 0.2 ? 2 : 1, 1);
  }
  for (let i = 0; i < 120; i++) {
    g.strokeStyle = `rgba(255,236,200,${0.008 + r() * 0.018})`;
    g.lineWidth = 1;
    const x = r() * W, y = r() * H;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x + 8 + r() * 34, y + (r() - .5) * 8); g.stroke();
  }
  return c;
}

function polygon(g, pts, fill, stroke, lw = 1) {
  g.beginPath();
  g.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) g.lineTo(pts[i][0], pts[i][1]);
  g.closePath();
  if (fill) { g.fillStyle = fill; g.fill(); }
  if (stroke) { g.strokeStyle = stroke; g.lineWidth = lw; g.stroke(); }
}

export function createRenderer(canvas) {
  const ctx = canvas.getContext('2d', { alpha: false });
  const paper = makePaper();
  const stars = [];
  const embers = [];
  const sr = rng(0x51A2F00D);
  for (let i = 0; i < 82; i++) {
    stars.push({ x: sr() * W, y: sr() * H, s: 0.4 + sr() * 1.6, a: 0.18 + sr() * 0.62, p: sr() * TAU, layer: sr() < .6 ? .12 : .24 });
  }
  for (let i = 0; i < 34; i++) {
    embers.push({ x: sr() * W, y: sr() * H, s: 0.7 + sr() * 1.8, sp: 5 + sr() * 18, p: sr() * TAU });
  }
  const constellations = [
    [[0.10, 0.19], [0.16, 0.14], [0.21, 0.22], [0.28, 0.18], [0.31, 0.27]],
    [[0.67, 0.12], [0.72, 0.08], [0.79, 0.14], [0.84, 0.09], [0.88, 0.18], [0.81, 0.22]],
    [[0.43, 0.31], [0.49, 0.27], [0.55, 0.33], [0.61, 0.29]],
  ];

  let DPR = 1;
  function setup() {
    DPR = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
    canvas.width = Math.round(W * DPR);
    canvas.height = Math.round(H * DPR);
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.imageSmoothingEnabled = true;
  }
  setup();

  function sy(worldY, camY, shake) { return H - (worldY - camY) * PPM + shake; }
  function sx(worldX, shake) { return worldX * PPM + shake; }

  function drawSky(scene) {
    const cam = scene.cameraY;
    const mid = cam + H / PPM * 0.5;
    const z = zoneAt(mid);
    const t = scene.t;
    const g = ctx.createLinearGradient(0, 0, 0, H);
    if (z.id === 'wood') {
      g.addColorStop(0, '#120d20'); g.addColorStop(0.42, '#251529'); g.addColorStop(1, '#2d1a27');
    } else if (z.id === 'wind') {
      g.addColorStop(0, '#09141f'); g.addColorStop(0.5, '#123039'); g.addColorStop(1, '#18312f');
    } else {
      g.addColorStop(0, '#0d0820'); g.addColorStop(0.52, '#211440'); g.addColorStop(1, '#2b1940');
    }
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);

    // moon / lantern halo
    const moonX = W * 0.76, moonY = 152 + Math.sin(t * 0.09) * 4;
    const halo = ctx.createRadialGradient(moonX, moonY, 6, moonX, moonY, 118);
    halo.addColorStop(0, z.id === 'wind' ? 'rgba(203,255,239,.34)' : 'rgba(255,226,158,.32)');
    halo.addColorStop(0.28, z.id === 'star' ? 'rgba(240,213,145,.12)' : 'rgba(224,181,111,.10)');
    halo.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = halo;
    ctx.beginPath(); ctx.arc(moonX, moonY, 118, 0, TAU); ctx.fill();
    ctx.fillStyle = z.id === 'wind' ? '#d7f4e4' : '#f2dfaa';
    ctx.globalAlpha = 0.68;
    ctx.beginPath(); ctx.arc(moonX, moonY, 34, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.22;
    ctx.beginPath(); ctx.arc(moonX - 7, moonY - 8, 34, 0, TAU); ctx.stroke();
    ctx.globalAlpha = 1;

    // parallax stars
    for (const s of stars) {
      let yy = (s.y - cam * s.layer * PPM * 0.08 + t * 1.2) % H;
      if (yy < 0) yy += H;
      const tw = 0.5 + 0.5 * Math.sin(t * 1.4 + s.p);
      ctx.fillStyle = `rgba(255,242,203,${s.a * (0.45 + tw * 0.55)})`;
      ctx.beginPath(); ctx.arc(s.x, yy, s.s * (0.8 + tw * 0.3), 0, TAU); ctx.fill();
    }

    // constellations in the star district
    if (z.id === 'star') {
      ctx.strokeStyle = 'rgba(255,232,171,.13)';
      ctx.lineWidth = 1;
      for (const c of constellations) {
        ctx.beginPath();
        c.forEach(([x, y], i) => i ? ctx.lineTo(x * W, y * H * 0.8 + 60) : ctx.moveTo(x * W, y * H * 0.8 + 60));
        ctx.stroke();
        for (const [x, y] of c) {
          ctx.fillStyle = 'rgba(255,240,190,.55)';
          ctx.beginPath(); ctx.arc(x * W, y * H * 0.8 + 60, 1.5, 0, TAU); ctx.fill();
        }
      }
    }

    // distant roof silhouettes / tower ribs
    ctx.save();
    ctx.globalAlpha = 0.54;
    ctx.fillStyle = z.id === 'wind' ? 'rgba(4,15,20,.72)' : 'rgba(10,6,18,.72)';
    const off = ((-cam * 2.3) % 290 + 290) % 290;
    for (let i = -1; i < 4; i++) {
      const bx = -80 + i * 190 + off * 0.18;
      ctx.beginPath();
      ctx.moveTo(bx, H);
      ctx.lineTo(bx + 14, H);
      ctx.lineTo(bx + 14, 300);
      ctx.lineTo(bx + 64, 268);
      ctx.lineTo(bx + 114, 300);
      ctx.lineTo(bx + 114, H);
      ctx.lineTo(bx + 128, H);
      ctx.lineTo(bx + 128, 282);
      ctx.lineTo(bx + 64, 238);
      ctx.lineTo(bx, 282);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,220,167,.08)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    ctx.restore();

    // zone-specific drifting weather
    if (z.id === 'wind') {
      ctx.strokeStyle = 'rgba(171,236,219,.10)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 12; i++) {
        const yy = (i * 83 + t * (24 + i * 3)) % H;
        const xx = ((i * 137 + t * (38 + i * 4)) % (W + 200)) - 100;
        ctx.beginPath();
        ctx.moveTo(xx, yy);
        ctx.bezierCurveTo(xx + 34, yy - 7, xx + 72, yy + 5, xx + 114, yy - 2);
        ctx.stroke();
      }
    } else if (z.id === 'wood') {
      for (const e of embers) {
        const yy = (e.y - t * e.sp) % H;
        const xx = e.x + Math.sin(t * 0.9 + e.p) * 9;
        ctx.fillStyle = `rgba(255,178,92,${0.12 + 0.16 * (0.5 + 0.5 * Math.sin(t + e.p))})`;
        ctx.beginPath(); ctx.arc(xx, yy < 0 ? yy + H : yy, e.s, 0, TAU); ctx.fill();
      }
    } else {
      ctx.fillStyle = 'rgba(236,219,158,.18)';
      for (let i = 0; i < 20; i++) {
        const xx = ((i * 71 + t * 6) % W);
        const yy = ((i * 137 + t * 11) % H);
        ctx.fillRect(xx, yy, 1, 1);
      }
    }

    // atmospheric haze bands
    for (let i = 0; i < 4; i++) {
      const yy = ((i * 251 + cam * 2.8 + t * 2) % (H + 160)) - 80;
      const fg = ctx.createLinearGradient(0, yy - 40, 0, yy + 40);
      fg.addColorStop(0, 'rgba(0,0,0,0)');
      fg.addColorStop(0.5, z.id === 'wind' ? 'rgba(120,208,190,.035)' : 'rgba(201,145,92,.032)');
      fg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = fg;
      ctx.fillRect(0, yy - 40, W, 80);
    }
  }

  function drawTowerFrame(scene) {
    const cam = scene.cameraY, sh = scene.shakeY;
    const z = zoneAt(cam + 25);
    const y0 = Math.floor(cam / 10) * 10 - 10;
    for (let wy = y0; wy < cam + H / PPM + 12; wy += 10) {
      const yy = sy(wy, cam, sh);
      const alpha = 0.3;
      // cross brace
      ctx.strokeStyle = z.id === 'wind' ? `rgba(104,181,163,${alpha})` : `rgba(146,87,55,${alpha})`;
      ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(8, yy); ctx.lineTo(W - 8, yy); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,226,176,.10)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(8, yy - 2); ctx.lineTo(W - 8, yy - 2); ctx.stroke();
      // side diagonals
      if (((wy / 10) | 0) % 2 === 0) {
        ctx.strokeStyle = z.id === 'star' ? 'rgba(212,182,108,.10)' : 'rgba(220,166,104,.09)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(14, yy); ctx.lineTo(66, yy + 72); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(W - 14, yy); ctx.lineTo(W - 66, yy + 72); ctx.stroke();
      }
    }
    // vertical boundary framing
    const vg = ctx.createLinearGradient(0, 0, 24, 0);
    vg.addColorStop(0, 'rgba(0,0,0,.46)'); vg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = vg; ctx.fillRect(0, 0, 24, H);
    const vg2 = ctx.createLinearGradient(W, 0, W - 24, 0);
    vg2.addColorStop(0, 'rgba(0,0,0,.46)'); vg2.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = vg2; ctx.fillRect(W - 24, 0, 24, H);
  }

  function drawWall(w, cam, sh, t) {
    const x = sx(w.x, sx(0, 0));
    const yTop = sy(w.y + w.h, cam, sh);
    const hh = w.h * PPM;
    const ww = w.w * PPM;
    if (yTop > H + 20 || yTop + hh < -20) return;
    const z = zoneAt(w.y + w.h / 2);
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.28)';
    ctx.fillRect(x + 4, yTop + 4, ww, hh);
    const g = ctx.createLinearGradient(x, 0, x + ww, 0);
    if (z.id === 'wind') {
      g.addColorStop(0, '#132e30'); g.addColorStop(0.55, '#1f4d48'); g.addColorStop(1, '#0c2125');
    } else if (z.id === 'star') {
      g.addColorStop(0, '#1b122e'); g.addColorStop(0.55, '#34214c'); g.addColorStop(1, '#140d26');
    } else {
      g.addColorStop(0, '#2a1819'); g.addColorStop(0.55, '#4a2a24'); g.addColorStop(1, '#211316');
    }
    ctx.fillStyle = g;
    ctx.fillRect(x, yTop, ww, hh);
    // cap
    ctx.fillStyle = z.accent;
    ctx.globalAlpha = 0.72;
    ctx.fillRect(x - 2, yTop - 2, ww + 4, 3);
    ctx.globalAlpha = 1;

    if (z.id === 'wood') {
      ctx.strokeStyle = 'rgba(255,197,125,.15)';
      ctx.lineWidth = 1;
      for (let i = 8; i < hh; i += 18) {
        ctx.beginPath(); ctx.moveTo(x + 3, yTop + i); ctx.lineTo(x + ww - 2, yTop + i); ctx.stroke();
      }
      ctx.fillStyle = 'rgba(19,12,15,.5)';
      for (let i = 14; i < hh; i += 38) {
        ctx.beginPath(); ctx.arc(x + ww * 0.5, yTop + i, 2, 0, TAU); ctx.fill();
      }
      // hanging talisman
      if (hh > 45) {
        ctx.fillStyle = 'rgba(227,203,158,.58)';
        ctx.fillRect(x + ww * .22, yTop + 13, ww * .48, 15);
        ctx.fillStyle = 'rgba(118,44,37,.72)';
        ctx.font = '9px "KaiTi","STKaiti",serif';
        ctx.textAlign = 'center';
        ctx.fillText('風', x + ww * .46, yTop + 24);
      }
    } else if (z.id === 'wind') {
      ctx.strokeStyle = 'rgba(152,235,208,.18)';
      ctx.lineWidth = 1;
      for (let i = 6; i < hh; i += 15) {
        ctx.beginPath(); ctx.moveTo(x + 2, yTop + i); ctx.lineTo(x + ww - 2, yTop + i + 1.5); ctx.stroke();
      }
      ctx.strokeStyle = 'rgba(12,35,35,.55)';
      for (let i = 23; i < hh; i += 52) {
        ctx.beginPath(); ctx.moveTo(x, yTop + i); ctx.lineTo(x + ww, yTop + i); ctx.lineWidth = 3; ctx.stroke();
      }
    } else {
      ctx.strokeStyle = 'rgba(231,198,112,.22)';
      ctx.lineWidth = 1;
      for (let i = 10; i < hh; i += 22) {
        ctx.beginPath(); ctx.moveTo(x + 2, yTop + i); ctx.lineTo(x + ww - 2, yTop + i); ctx.stroke();
      }
      ctx.strokeStyle = 'rgba(229,193,104,.28)';
      ctx.beginPath();
      ctx.moveTo(x + ww * .5, yTop + 8);
      ctx.lineTo(x + ww * .5, yTop + hh - 8);
      ctx.stroke();
      for (let i = 28; i < hh; i += 60) {
        ctx.strokeStyle = 'rgba(229,193,104,.42)';
        ctx.beginPath(); ctx.arc(x + ww * .5, yTop + i, 5, 0, TAU); ctx.stroke();
      }
    }
    // inner pillar gets a paper-cut notch
    if (w.inner) {
      ctx.fillStyle = z.accent2;
      ctx.globalAlpha = .7;
      polygon(ctx, [[x, yTop], [x - 5, yTop + 8], [x, yTop + 16]], z.accent2);
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  }

  function drawPlatform(p, cam, sh, t) {
    const x = sx(p.x, sceneShakeX);
    const top = sy(p.y, cam, sh);
    const w = p.w * PPM;
    const h = Math.max(8, p.h * PPM);
    if (top > H + 30 || top + h < -30) return;
    const z = zoneAt(p.y);
    ctx.save();
    // paper shadow
    ctx.fillStyle = 'rgba(0,0,0,.25)';
    ctx.fillRect(x + 4, top + 7, w, h + 2);

    const g = ctx.createLinearGradient(0, top, 0, top + h);
    if (p.kind === 'finish') {
      g.addColorStop(0, '#e2c06d'); g.addColorStop(1, '#5d3b38');
    } else if (z.id === 'wind') {
      g.addColorStop(0, '#285a51'); g.addColorStop(0.24, '#80cbb6'); g.addColorStop(0.3, '#2c5b52'); g.addColorStop(1, '#122e2c');
    } else if (z.id === 'star') {
      g.addColorStop(0, '#3a2857'); g.addColorStop(0.22, '#e0bd6b'); g.addColorStop(0.28, '#3a2853'); g.addColorStop(1, '#171026');
    } else {
      g.addColorStop(0, '#4f2b25'); g.addColorStop(0.22, '#d99a55'); g.addColorStop(0.29, '#5a3027'); g.addColorStop(1, '#281618');
    }
    ctx.fillStyle = g;
    ctx.fillRect(x, top, w, h);

    // top light lip
    ctx.fillStyle = z.glow;
    ctx.globalAlpha = p.checkpoint ? .95 : .64;
    ctx.fillRect(x + 1, top, w - 2, 2);
    ctx.globalAlpha = 1;

    // ink wood grain
    ctx.strokeStyle = z.id === 'wind' ? 'rgba(9,31,30,.42)' : z.id === 'star' ? 'rgba(15,8,26,.5)' : 'rgba(29,13,12,.42)';
    ctx.lineWidth = 1;
    for (let i = 10; i < w - 8; i += 22 + ((p.seed * 17) | 0) % 9) {
      ctx.beginPath();
      ctx.moveTo(x + i, top + 4);
      ctx.bezierCurveTo(x + i + 7, top + h * .35, x + i - 4, top + h * .65, x + i + 10, top + h - 2);
      ctx.stroke();
    }

    // paper-cut teeth under the edge
    ctx.fillStyle = z.ink;
    ctx.globalAlpha = .45;
    for (let i = 4; i < w - 2; i += 22) {
      polygon(ctx, [[x + i, top + h], [x + i + 7, top + h + 5], [x + i + 14, top + h]], z.ink);
    }
    ctx.globalAlpha = 1;

    // copper end caps
    ctx.fillStyle = z.id === 'wind' ? '#8de0c5' : '#d9aa62';
    ctx.globalAlpha = .7;
    ctx.fillRect(x - 3, top - 1, 3, h + 1);
    ctx.fillRect(x + w, top - 1, 3, h + 1);
    ctx.globalAlpha = 1;

    if (p.checkpoint) {
      ctx.strokeStyle = 'rgba(255,228,155,.7)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x - 1.5, top - 1.5, w + 3, h + 2);
      ctx.fillStyle = 'rgba(255,225,147,.85)';
      ctx.font = 'bold 9px "KaiTi","STKaiti",serif';
      ctx.textAlign = 'center';
      ctx.fillText('灯 标', x + w / 2, top + h + 14);
    }
    ctx.restore();
  }

  function drawHazard(h, cam, sh, t) {
    const x = sx(h.x, sceneShakeX);
    const top = sy(h.y, cam, sh);
    const w = h.w * PPM;
    if (top > H + 20 || top < -30) return;
    if (h.kind === 'caltrop') {
      ctx.save();
      ctx.fillStyle = 'rgba(255,88,66,.1)';
      ctx.beginPath(); ctx.ellipse(x + w / 2, top + 1, w * .72, 5, 0, 0, TAU); ctx.fill();
      for (let i = 0; i < 4; i++) {
        const bx = x + 3 + i * (w - 6) / 4;
        polygon(ctx, [[bx, top], [bx + 5, top - 10 - (i % 2) * 2], [bx + 10, top]], '#bd4434', 'rgba(255,177,130,.55)', 0.7);
        ctx.fillStyle = 'rgba(255,205,157,.8)';
        ctx.fillRect(bx + 4.5, top - 4, 1, 3);
        ctx.fillStyle = '#bd4434';
      }
      ctx.restore();
      return;
    }
    const active = h.active;
    const warn = h.warn;
    ctx.save();
    // socket
    ctx.fillStyle = '#181020';
    ctx.fillRect(x, top - 3, w, 4);
    ctx.fillStyle = warn ? 'rgba(224,79,55,.46)' : 'rgba(100,72,94,.55)';
    ctx.fillRect(x + 1, top - 2, w - 2, 1.5);
    if (warn) {
      const pulse = .5 + .5 * Math.sin(t * 18);
      const gr = ctx.createRadialGradient(x + w / 2, top - 10, 2, x + w / 2, top - 10, w * .9);
      gr.addColorStop(0, `rgba(255,94,64,${.22 + pulse * .2})`);
      gr.addColorStop(1, 'rgba(255,94,64,0)');
      ctx.fillStyle = gr;
      ctx.beginPath(); ctx.arc(x + w / 2, top - 8, w * .9, 0, TAU); ctx.fill();
      ctx.strokeStyle = `rgba(255,164,112,${.35 + pulse * .45})`;
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.ellipse(x + w / 2, top - 1, w * .62, 3.5, 0, 0, TAU); ctx.stroke();
      ctx.fillStyle = `rgba(255,210,160,${.55 + pulse * .35})`;
      ctx.font = 'bold 10px "KaiTi",serif';
      ctx.textAlign = 'center';
      ctx.fillText('!', x + w / 2, top - 13);
    }
    if (active) {
      for (let i = 0; i < 5; i++) {
        const bx = x + 1 + i * (w - 2) / 5;
        polygon(ctx, [[bx, top], [bx + 4.4, top - 14], [bx + 8.8, top]], '#cf4a36', 'rgba(255,179,125,.6)', .7);
      }
      ctx.fillStyle = 'rgba(255,120,80,.16)';
      ctx.beginPath(); ctx.ellipse(x + w / 2, top - 1, w * .62, 4, 0, 0, TAU); ctx.fill();
    } else if (!warn) {
      // retracted teeth slots
      for (let i = 0; i < 5; i++) {
        const bx = x + 2 + i * (w - 4) / 5;
        ctx.fillStyle = 'rgba(121,83,104,.5)';
        ctx.fillRect(bx, top - 1, 5, 1.5);
      }
    }
    ctx.restore();
  }

  function drawPickup(p, cam, sh, t) {
    if (p.taken) return;
    const x = sx(p.x, sceneShakeX);
    const y = sy(p.y + Math.sin(t * 2.3 + p.phase) * 0.18, cam, sh);
    if (x < -20 || x > W + 20 || y < -20 || y > H + 20) return;
    const pulse = .72 + .28 * Math.sin(t * 3 + p.phase);
    ctx.save();
    const g = ctx.createRadialGradient(x, y, 0, x, y, 20);
    g.addColorStop(0, `rgba(255,234,160,${.45 * pulse})`);
    g.addColorStop(.35, `rgba(255,184,83,${.18 * pulse})`);
    g.addColorStop(1, 'rgba(255,184,83,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, 20, 0, TAU); ctx.fill();
    ctx.translate(x, y);
    ctx.rotate(t * .7 + p.phase);
    ctx.fillStyle = '#ffe3a0';
    ctx.beginPath();
    ctx.moveTo(0, -5.5); ctx.quadraticCurveTo(2.2, -2.2, 5.5, 0);
    ctx.quadraticCurveTo(2.2, 2.2, 0, 5.5); ctx.quadraticCurveTo(-2.2, 2.2, -5.5, 0);
    ctx.quadraticCurveTo(-2.2, -2.2, 0, -5.5);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,225,.8)';
    ctx.lineWidth = .8;
    ctx.beginPath(); ctx.moveTo(0, -3); ctx.lineTo(0, 3); ctx.stroke();
    ctx.restore();
  }

  function drawLantern(l, cam, sh, t) {
    const x = sx(l.x, sceneShakeX);
    const y = sy(l.y + Math.sin(t * 1.1 + l.phase) * 0.12, cam, sh);
    if (x < -40 || x > W + 40 || y < -40 || y > H + 40) return;
    const z = zoneAt(l.y);
    ctx.save();
    ctx.strokeStyle = 'rgba(35,22,32,.7)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x, y - 25); ctx.lineTo(x, y - 9); ctx.stroke();
    const glow = ctx.createRadialGradient(x, y, 1, x, y, 28);
    glow.addColorStop(0, z.id === 'wind' ? 'rgba(162,255,224,.24)' : 'rgba(255,210,126,.25)');
    glow.addColorStop(1, 'rgba(255,180,80,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(x, y, 28, 0, TAU); ctx.fill();
    ctx.fillStyle = z.id === 'wind' ? 'rgba(159,231,211,.8)' : z.id === 'star' ? 'rgba(244,226,165,.85)' : 'rgba(238,184,105,.85)';
    ctx.beginPath(); ctx.ellipse(x, y - 3, 5 * l.scale, 8 * l.scale, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(30,20,26,.8)';
    ctx.fillRect(x - 5 * l.scale, y - 11 * l.scale, 10 * l.scale, 2);
    ctx.fillRect(x - 3 * l.scale, y + 5 * l.scale, 6 * l.scale, 1.5);
    ctx.restore();
  }

  function drawGate(g, cam, sh, t, checkpointY, mode) {
    const x = sx(g.x, sceneShakeX);
    const y = sy(g.y, cam, sh);
    if (y > H + 130 || y < -160) return;
    const active = g.height <= checkpointY || (g.finish && mode === 'win');
    const z = zoneAt(g.y);
    const half = g.finish ? 4.6 : 3.1;
    ctx.save();
    // glow on the deck
    const gl = ctx.createRadialGradient(x, y - 16, 2, x, y - 16, 70);
    gl.addColorStop(0, active ? 'rgba(137,237,203,.22)' : 'rgba(220,170,95,.10)');
    gl.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = gl;
    ctx.beginPath(); ctx.arc(x, y - 16, 70, 0, TAU); ctx.fill();

    // posts
    ctx.lineCap = 'round';
    ctx.strokeStyle = g.finish ? '#e3c374' : z.accent;
    ctx.lineWidth = g.finish ? 4 : 3;
    ctx.beginPath(); ctx.moveTo(x - half * PPM, y); ctx.lineTo(x - half * PPM, y - 58); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x + half * PPM, y); ctx.lineTo(x + half * PPM, y - 58); ctx.stroke();
    // curved lintel
    ctx.lineWidth = g.finish ? 5 : 3.5;
    ctx.beginPath();
    ctx.moveTo(x - half * PPM - 9, y - 54);
    ctx.quadraticCurveTo(x, y - 70, x + half * PPM + 9, y - 54);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255,238,188,.38)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x - half * PPM - 9, y - 57);
    ctx.quadraticCurveTo(x, y - 73, x + half * PPM + 9, y - 57);
    ctx.stroke();

    // hanging lantern
    const swing = Math.sin(t * 1.2 + g.idx) * 3;
    ctx.strokeStyle = 'rgba(54,30,33,.7)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x, y - 59); ctx.lineTo(x + swing, y - 39); ctx.stroke();
    const lg = ctx.createRadialGradient(x + swing, y - 32, 1, x + swing, y - 32, 32);
    lg.addColorStop(0, active ? 'rgba(169,255,220,.5)' : 'rgba(255,209,126,.32)');
    lg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = lg;
    ctx.beginPath(); ctx.arc(x + swing, y - 32, 32, 0, TAU); ctx.fill();
    ctx.fillStyle = active ? '#a9f0d2' : '#e8b76f';
    ctx.beginPath(); ctx.ellipse(x + swing, y - 33, 6.5, 10, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(32,21,26,.8)';
    ctx.fillRect(x + swing - 6, y - 44, 12, 2);
    if (active) {
      ctx.strokeStyle = 'rgba(159,240,207,.45)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(x + swing, y - 33, 17 + Math.sin(t * 2) * 2, 0, TAU); ctx.stroke();
    }
    // height plaque
    ctx.fillStyle = 'rgba(22,14,24,.62)';
    ctx.fillRect(x - 18, y - 52, 36, 13);
    ctx.fillStyle = active ? '#b9f3d9' : '#e5bf7b';
    ctx.font = '9px "KaiTi","STKaiti",serif';
    ctx.textAlign = 'center';
    ctx.fillText(g.finish ? '星阁' : `${g.height}m`, x, y - 42);

    if (g.finish) {
      ctx.fillStyle = 'rgba(255,233,162,.14)';
      ctx.beginPath(); ctx.arc(x, y - 108, 42, 0, TAU); ctx.fill();
      ctx.strokeStyle = 'rgba(255,233,162,.4)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(x, y - 108, 42, 0, TAU); ctx.stroke();
      ctx.fillStyle = 'rgba(255,238,185,.8)';
      ctx.beginPath(); ctx.arc(x, y - 108, 23, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  function drawScarf(p, cam, sh, t) {
    const pts = p.trail || [];
    if (pts.length < 2) return;
    ctx.save();
    ctx.lineCap = 'round';
    for (let pass = 0; pass < 2; pass++) {
      ctx.beginPath();
      for (let i = 0; i < pts.length; i++) {
        const q = pts[i];
        const x = sx(q.x, sceneShakeX);
        const y = sy(q.y, cam, sh);
        if (i === 0) ctx.moveTo(x, y);
        else {
          const prev = pts[i - 1];
          const px = sx(prev.x, sceneShakeX), py = sy(prev.y, cam, sh);
          ctx.quadraticCurveTo((px + x) / 2, (py + y) / 2 + Math.sin(t * 6 + i) * 1.5, x, y);
        }
      }
      ctx.strokeStyle = pass === 0 ? 'rgba(106,32,33,.55)' : '#c84e3b';
      ctx.lineWidth = pass === 0 ? 7 : 3.4;
      ctx.globalAlpha = pass === 0 ? .55 : .9;
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawPlayer(p, cam, sh, t, scene) {
    if (p.invulnT > 0 && Math.floor(t * 25) % 2 === 0 && !p.dashT) return;
    const x = sx(p.x, sceneShakeX);
    const feet = sy(p.y, cam, sh);
    if (x < -100 || x > W + 100 || feet < -100 || feet > H + 100) return;

    // dash afterimages
    if (scene.ghosts && scene.ghosts.length) {
      for (const gh of scene.ghosts) {
        const gx = sx(gh.x, sceneShakeX), gy = sy(gh.y, cam, sh);
        ctx.save();
        ctx.globalAlpha = gh.life * .22;
        ctx.fillStyle = '#c84e3b';
        ctx.beginPath(); ctx.ellipse(gx, gy - 15, 8, 17, gh.rot || 0, 0, TAU); ctx.fill();
        ctx.restore();
      }
    }

    ctx.save();
    ctx.translate(x, feet);
    // ground shadow
    const air = Math.max(0, Math.min(1, 1 - Math.abs(p.vy) / 12));
    ctx.fillStyle = `rgba(0,0,0,${0.18 + air * 0.12})`;
    ctx.beginPath(); ctx.ellipse(0, 2, 11, 3.4, 0, 0, TAU); ctx.fill();

    const face = p.face >= 0 ? 1 : -1;
    ctx.scale(face, 1);
    const speed = Math.min(1, Math.abs(p.vx) / 7.5);
    const run = p.grounded ? Math.sin(t * 15 + speed * 5) * (0.35 + speed * 0.8) : 0;
    const bob = p.grounded ? Math.abs(Math.sin(t * 15)) * 1.2 * speed : 0;
    const lean = p.dashT ? 0.25 : 0;
    const tilt = p.dashT ? 0.45 : p.wallDir ? -p.wallDir * face * 0.16 : 0;

    // scarf trail
    drawScarf(p, cam, sh, t);

    ctx.rotate(tilt);
    ctx.translate(0, -bob);

    // legs
    ctx.strokeStyle = '#17152b';
    ctx.lineWidth = 3.2;
    ctx.lineCap = 'round';
    if (p.dashT) {
      ctx.beginPath(); ctx.moveTo(-1, -10); ctx.lineTo(-11, -7); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-1, -10); ctx.lineTo(-8, -2); ctx.stroke();
    } else if (!p.grounded) {
      const tuck = p.vy > 0 ? 4 : 2;
      ctx.beginPath(); ctx.moveTo(0, -11); ctx.lineTo(-4, -6 - tuck); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(1, -11); ctx.lineTo(7, -8 - tuck); ctx.stroke();
    } else {
      ctx.beginPath(); ctx.moveTo(0, -11); ctx.lineTo(run * 7 - 2, -1); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(1, -11); ctx.lineTo(-run * 7 + 3, -1); ctx.stroke();
    }
    // body (tapered ink stroke)
    ctx.fillStyle = '#1b1830';
    ctx.beginPath();
    ctx.moveTo(-5, -25);
    ctx.quadraticCurveTo(-7, -16, -4, -9);
    ctx.quadraticCurveTo(0, -6, 5, -10);
    ctx.quadraticCurveTo(7, -18, 4, -25);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#302a4c';
    ctx.beginPath(); ctx.ellipse(-1, -18, 3.3, 6, -0.1, 0, TAU); ctx.fill();
    // sash
    ctx.fillStyle = '#b84a38';
    ctx.fillRect(-5, -14, 10, 2.2);
    // arms
    ctx.strokeStyle = '#17152b';
    ctx.lineWidth = 2.8;
    if (p.dashT) {
      ctx.beginPath(); ctx.moveTo(2, -22); ctx.lineTo(-9, -23); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-3, -21); ctx.lineTo(-12, -17); ctx.stroke();
    } else if (p.wallDir) {
      ctx.beginPath(); ctx.moveTo(2, -22); ctx.lineTo(9, -18); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-2, -21); ctx.lineTo(-6, -14); ctx.stroke();
    } else {
      ctx.beginPath(); ctx.moveTo(2, -22); ctx.lineTo(6 - run * 2, -15); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-3, -21); ctx.lineTo(-6 + run * 2, -15); ctx.stroke();
    }
    // head + mask
    ctx.fillStyle = '#d9a46e';
    ctx.beginPath(); ctx.arc(1, -29, 5.1, 0, TAU); ctx.fill();
    ctx.fillStyle = '#1b1830';
    ctx.beginPath(); ctx.arc(0.2, -30.3, 5.3, Math.PI * 0.86, Math.PI * 2.06); ctx.fill();
    ctx.fillStyle = '#b84a38';
    ctx.fillRect(-4.2, -32.4, 9.8, 2.1);
    // eyes + headband tail
    ctx.fillStyle = '#b7f2d1';
    ctx.fillRect(2.6, -29.1, 2.0, 1.2);
    ctx.strokeStyle = '#c84e3b';
    ctx.lineWidth = 1.4;
    const tail = Math.sin(t * 7.5) * 2;
    ctx.beginPath(); ctx.moveTo(-4, -31); ctx.quadraticCurveTo(-10, -33 + tail, -14, -28 + tail); ctx.stroke();
    // blade on the back
    ctx.save();
    ctx.rotate(-0.58);
    ctx.strokeStyle = 'rgba(203,238,226,.75)';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(-4, -8); ctx.lineTo(-2, -28); ctx.stroke();
    ctx.strokeStyle = '#d9aa62';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-4.8, -7); ctx.lineTo(-1, -2); ctx.stroke();
    ctx.restore();

    // dash speed streaks
    if (p.dashT) {
      ctx.strokeStyle = 'rgba(255,226,166,.55)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(-14 - i * 5, -23 + i * 6);
        ctx.lineTo(-27 - i * 8, -23 + i * 6);
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  function drawParticles(scene, cam, sh) {
    ctx.save();
    for (const p of scene.particles) {
      const x = sx(p.x, sceneShakeX), y = sy(p.y, cam, sh);
      const a = Math.max(0, Math.min(1, p.life / p.max));
      if (p.type === 'ring') {
        ctx.strokeStyle = p.color;
        ctx.globalAlpha = a * .7;
        ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(x, y, p.size * (1.8 - a * 1.2), 0, TAU); ctx.stroke();
      } else if (p.type === 'spark') {
        ctx.globalAlpha = a;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size * .6;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - p.vx * .035, y + p.vy * .035); ctx.stroke();
      } else if (p.type === 'shard') {
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        ctx.save(); ctx.translate(x, y); ctx.rotate(p.rot || 0);
        polygon(ctx, [[-2, -4], [3, -1], [1, 4], [-3, 2]], p.color);
        ctx.restore();
      } else {
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(x, y, p.size * (.6 + (1 - a) * .5), 0, TAU); ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
    for (const f of scene.floats) {
      const x = sx(f.x, sceneShakeX), y = sy(f.y, cam, sh);
      const a = Math.max(0, Math.min(1, f.life / f.max));
      ctx.globalAlpha = a;
      ctx.font = 'bold 11px "KaiTi","STKaiti",serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(0,0,0,.42)';
      ctx.fillText(f.text, x + 1, y + 1);
      ctx.fillStyle = f.color || '#ffe5a8';
      ctx.fillText(f.text, x, y);
    }
    ctx.restore();
  }

  function drawForeground(scene) {
    const z = zoneAt(scene.cameraY + 25);
    // vignette
    const v = ctx.createRadialGradient(W / 2, H * .48, H * .24, W / 2, H * .48, H * .66);
    v.addColorStop(0, 'rgba(0,0,0,0)');
    v.addColorStop(.72, 'rgba(3,2,9,.12)');
    v.addColorStop(1, 'rgba(3,2,9,.58)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, W, H);
    // paper grain
    ctx.globalAlpha = .5;
    ctx.drawImage(paper, 0, 0);
    ctx.globalAlpha = 1;
    // hit flashes
    if (scene.flashT > 0) {
      ctx.fillStyle = `rgba(255,92,61,${Math.min(.28, scene.flashT * .65)})`;
      ctx.fillRect(0, 0, W, H);
    }
    if (scene.flowT > 0) {
      ctx.strokeStyle = 'rgba(255,220,146,.16)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 7; i++) {
        const yy = (i * 131 + scene.t * 380) % H;
        ctx.beginPath(); ctx.moveTo(0, yy); ctx.lineTo(W, yy + 1); ctx.stroke();
      }
    }
    if (scene.mode === 'title') {
      ctx.fillStyle = 'rgba(8,5,16,.26)';
      ctx.fillRect(0, 0, W, H);
    }
    // thin gold frame
    ctx.strokeStyle = `rgba(231,193,113,${z.id === 'wind' ? .18 : .22})`;
    ctx.lineWidth = 1;
    ctx.strokeRect(7.5, 7.5, W - 15, H - 15);
    ctx.strokeStyle = 'rgba(0,0,0,.5)';
    ctx.strokeRect(9.5, 9.5, W - 19, H - 19);
  }

  // module-scope shake state, assigned each draw; kept simple and deterministic
  let sceneShakeX = 0, sceneShakeY = 0;

  function draw(scene) {
    sceneShakeX = scene.shakeX || 0;
    sceneShakeY = scene.shakeY || 0;
    const cam = scene.cameraY;
    const sh = sceneShakeY;
    ctx.save();
    drawSky(scene);
    ctx.save();
    ctx.translate(sceneShakeX, 0);

    drawTowerFrame(scene);

    // lanterns and gates behind ledges
    for (const l of scene.level.lanterns) drawLantern(l, cam, sh, scene.t);
    for (const g of scene.level.gates) drawGate(g, cam, sh, scene.t, scene.checkpointY, scene.mode);

    for (const w of scene.level.walls) drawWall(w, cam, sh, scene.t);
    for (const p of scene.level.platforms) drawPlatform(p, cam, sh, scene.t);
    for (const h of scene.level.hazards) drawHazard(h, cam, sh, scene.t);
    for (const p of scene.level.pickups) drawPickup(p, cam, sh, scene.t);
    if (scene.mode !== 'title' || scene.showPlayer) drawPlayer(scene.player, cam, sh, scene.t, scene);
    drawParticles(scene, cam, sh);
    ctx.restore();

    drawForeground(scene);
    ctx.restore();
  }

  return { draw, setup, W, H };
}

input.content:
// Shadowspire Ninja 影峰登天 — a vertical wall-jump tower climb.
// Vanilla ES module, fixed-step physics, procedural canvas art, WebAudio synth,
// site report bridge, debug G hooks and a deterministic ?autotest=1 suite.

import { CFG, zoneAt, buildLevel, surfaceBelow, routeStats } from './level.js';
import { makeAudio } from './audio.js';
import { makeUI } from './ui.js';
import { createRenderer } from './render.js';

const DT = 1 / 60;
const W = CFG.W, H = CFG.H, PPM = CFG.PPM;
const WORLD_W = CFG.WORLD_W, WORLD_H = CFG.WORLD_H;
const PARAMS = new URLSearchParams(location.search);
const AUTOTEST = PARAMS.has('autotest');
const AUTOSTART = PARAMS.get('autostart') === '1' || PARAMS.has('auto');

// --- feel / balance table -------------------------------------------------
const GRAV = 47;
const MAX_FALL = -22;
const MOVE = 7.7;
const GROUND_ACC = 58;
const AIR_ACC = 31;
const GROUND_FRICTION = 55;
const AIR_DRAG = 10;
const JUMP_V = 19.6;
const COYOTE = 0.11;
const JUMP_BUFFER = 0.12;
const WALL_SLIDE = 4.3;
const WALL_JUMP_X = 9.4;
const WALL_JUMP_Y = 17.7;
const MAX_CHI = 100;
const DASH_COST = 24;
const DASH_SPEED = 27;
const DASH_TIME = 0.16;
const DASH_CD = 0.38;
const DASH_IFRAME = 0.23;
const HITSTOP_DEATH = 0.085;
const HITSTOP_FLOW = 0.07;
const FLOW_TIME = 3.2;
const FLOW_MULT = 1.28;
const FLOW_BONUS = 200;
const WALL_DASH_BONUS = 120;
const DUST_CHI = 18;
const DUST_SCORE = 25;
const HEIGHT_SCORE = 2;
const CP_BONUS = 300;
const START_LIVES = 3;
const PW = 0.78, PH = 1.72;
const HALF_W = PW / 2;

const __BOOTERR = window.__BOOTERR || (window.__BOOTERR = []);

// --- modules --------------------------------------------------------------
const canvas = document.getElementById('cv');
const renderer = createRenderer(canvas);
const level = buildLevel();
const audio = makeAudio({ autotest: AUTOTEST });
const levelRoute = routeStats(level);

let reportTarget = null;
const reports = [];
function report(kind, payload = {}) {
  const frame = { kind, ...payload };
  if (frame.score != null) frame.score = Math.round(frame.score);
  if (frame.progress != null) frame.progress = Math.round(frame.progress);
  reports.push(frame);
  try {
    if (reportTarget) reportTarget(frame);
    else if (window.parent !== window) {
      window.parent.postMessage(
        { source: 'lightgame', type: 'lightgame:report', payload: frame }, '*'
      );
    }
  } catch (e) { }
}
report('ready', { game: 'shadowspire-ninja' });

// --- state ----------------------------------------------------------------
let mode = 'title';             // title | play | over | win
let paused = false;
let noAuto = false;
let lives = START_LIVES;
let score = 0;
let dust = 0;
let chi = MAX_CHI;
let best = 0;
try { best = Math.max(0, parseInt(localStorage.getItem('ssn.best') || '0', 10) || 0); } catch (e) { }

let maxHeight = CFG.START_Y;
let lastScoredHeight = 0;
let checkpointY = 0;
let nextCpIndex = 1;
let cpSpawn = { x: 15, y: CFG.START_Y + 0.02 };
let runT = 0;
let ambientT = 0;
let endCause = '';
let hitstop = 0;
let shakeAmp = 0;
let flashT = 0;
let hintWall = false;
let hintDash = false;
let trailAcc = 0, ghostAcc = 0, dustAcc = 0;
let cameraY = -5;

const held = new Set();
const pressed = new Set();
const touch = { left: false, right: false, jump: false, dash: false };

const player = {
  x: 15, y: CFG.START_Y + 0.02, vx: 0, vy: 0, face: 1,
  grounded: true, coyote: 0, jumpBuf: 0, wallDir: 0,
  wallJumps: 0, flowT: 0, wallFreshT: 0,
  dashT: 0, dashCd: 0, dashDir: 1, invulnT: 0,
  trail: [],
};

const particles = [];
const floats = [];
const ghosts = [];

const ui = makeUI({
  onStart: () => { audio.unlock(); startGame(); },
  onRestart: () => { audio.unlock(); startGame(); },
  onBackTitle: () => { audio.play('ui'); toTitle(); },
  onMute: () => toggleMute(),
  onPause: () => togglePause(),
  onShare: () => {
    try {
      if (typeof window.dp_share === 'function') window.dp_share(Math.floor(maxHeight));
    } catch (e) { }
  },
});

// --- little helpers -------------------------------------------------------
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const approach = (v, target, delta) => v < target ? Math.min(target, v + delta) : Math.max(target, v - delta);
const rnd = (a, b) => a + Math.random() * (b - a);
const isJumpDown = () => pressed.has('Space') || pressed.has('KeyW') || pressed.has('ArrowUp');
const isJumpHeld = () => held.has('Space') || held.has('KeyW') || held.has('ArrowUp') || touch.jump;
const isDashDown = () => pressed.has('ShiftLeft') || pressed.has('ShiftRight') || pressed.has('KeyK');
const isLeft = () => held.has('KeyA') || held.has('ArrowLeft') || touch.left;
const isRight = () => held.has('KeyD') || held.has('ArrowRight') || touch.right;

function zoneNow() { return zoneAt(Math.max(0, Math.min(WORLD_H - 0.01, player.y))); }

function addShake(n) { shakeAmp = Math.min(8, shakeAmp + n); }
function addHitstop(n) { hitstop = Math.max(hitstop, n); }

function spawnParticle(x, y, vx, vy, type, color, life, size, extra = {}) {
  if (particles.length > 260) particles.shift();
  particles.push({ x, y, vx, vy, type, color, life, max: life, size, grav: 0, rot: 0, ...extra });
}
function burst(x, y, n, colors, spd = 6, opts = {}) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = spd * (0.32 + Math.random() * 0.85);
    spawnParticle(
      x, y, Math.cos(a) * s, Math.sin(a) * s + (opts.up || 0),
      opts.type || 'spark', colors[(Math.random() * colors.length) | 0],
      (opts.life || 0.55) * (0.6 + Math.random() * 0.7),
      (opts.size || 2) * (0.7 + Math.random() * 0.8),
      { grav: opts.grav == null ? 8 : opts.grav }
    );
  }
}
function ring(x, y, color, size = 2, life = 0.42) {
  spawnParticle(x, y, 0, 0, 'ring', color, life, size, { grav: 0 });
}
function floatText(x, y, text, color = '#ffe5a8') {
  if (floats.length > 16) floats.shift();
  floats.push({ x, y, text, color, life: 0.95, max: 0.95 });
}

function clearPressed() { pressed.clear(); }

function loadMutedUI() { ui.setMuted(audio.muted); }

// --- flow / reset ---------------------------------------------------------
function resetPickupsAndHazards() {
  for (const p of level.pickups) p.taken = false;
  for (const h of level.hazards) {
    if (!h.static) { h.active = false; h.warn = false; }
    else { h.active = true; h.warn = false; }
  }
}

function resetPlayer() {
  player.x = 15; player.y = CFG.START_Y + 0.02;
  player.vx = 0; player.vy = 0; player.face = 1;
  player.grounded = true; player.coyote = COYOTE; player.jumpBuf = 0; player.wallDir = 0;
  player.wallJumps = 0; player.flowT = 0; player.wallFreshT = 0;
  player.dashT = 0; player.dashCd = 0; player.dashDir = 1; player.invulnT = 0;
  player.trail.length = 0;
}

function resetRun() {
  lives = START_LIVES;
  score = 0; dust = 0; chi = MAX_CHI;
  maxHeight = CFG.START_Y; lastScoredHeight = Math.floor(CFG.START_Y);
  checkpointY = 0; nextCpIndex = 1;
  cpSpawn = { x: 15, y: CFG.START_Y + 0.02 };
  runT = 0; hitstop = 0; shakeAmp = 0; flashT = 0;
  hintWall = false; hintDash = false;
  trailAcc = 0; ghostAcc = 0; dustAcc = 0;
  particles.length = 0; floats.length = 0; ghosts.length = 0;
  resetPickupsAndHazards();
  resetPlayer();
}

function snapCamera() {
  cameraY = clamp(player.y - 17.8, -5, WORLD_H - 18);
}

function startGame() {
  resetRun();
  mode = 'play'; paused = false; endCause = '';
  snapCamera();
  ui.showTitle(false); ui.hideEnd(); ui.showPause(false); ui.setPaused(false);
  ui.setBest(best);
  audio.setState(zoneNow().id);
  ui.toast('A/D 横移 · 空格起跃 · 贴墙再按空格蹬墙 · Shift 冲刺', 4600);
  report('progress', { score: 0, progress: 0 });
}

function toTitle() {
  resetRun();
  mode = 'title'; paused = false;
  snapCamera();
  ui.showTitle(true); ui.hideEnd(); ui.showPause(false); ui.setPaused(false);
  ui.setBest(best);
  audio.setState('title');
}

function togglePause(force) {
  if (mode !== 'play') return;
  paused = force == null ? !paused : !!force;
  ui.setPaused(paused);
  if (paused) {
    ui.toast('入定 · P 继续', 1200);
    audio.setState('title');
  } else {
    audio.setState(zoneNow().id);
  }
}

function toggleMute() {
  audio.toggleMute();
  ui.setMuted(audio.muted);
  ui.toast(audio.muted ? '已静音 · M 恢复' : '声音已开 · M 静音', 1200);
}

function saveBest() {
  const h = Math.max(0, Math.floor(maxHeight));
  if (h > best) {
    best = h;
    try { localStorage.setItem('ssn.best', String(best)); } catch (e) { }
    ui.setBest(best);
    return true;
  }
  return false;
}

function gameOver(cause = '灯焰熄灭') {
  if (mode !== 'play') {
    if (mode === 'over') return;
  }
  endCause = cause;
  mode = 'over'; paused = false;
  saveBest();
  ui.setPaused(false);
  ui.showPause(false);
  report('gameOver', { score, progress: Math.floor(maxHeight), cause });
  audio.setState('title');
  audio.play('over');
  ui.showEnd({ kind: 'over', score: Math.floor(score), height: Math.floor(maxHeight), best, time: runT, cause });
}

function win() {
  if (mode !== 'play') return;
  mode = 'win'; paused = false;
  maxHeight = WORLD_H;
  score += 1000;
  saveBest();
  ui.setPaused(false);
  ui.showPause(false);
  report('complete', { score, progress: WORLD_H });
  audio.setState('win');
  audio.play('win');
  burst(player.x, player.y + 1, 42, ['#fff0b5', '#e4c06f', '#9fe8c8', '#c84e3b'], 10, { size: 2.4, life: 1.4, up: 4 });
  ui.showEnd({ kind: 'win', score: Math.floor(score), height: WORLD_H, best, time: runT });
}

function damage(cause = '刺阵') {
  if (mode !== 'play' || player.invulnT > 0) return false;
  lives--;
  endCause = cause;
  hitstop = HITSTOP_DEATH;
  addShake(7);
  flashT = 0.3;
  burst(player.x, player.y + 0.8, 24, ['#d9493a', '#f3a45f', '#ffe0a8'], 8, { size: 2.8, life: 0.7, up: 2 });
  ring(player.x, player.y + 0.8, 'rgba(255,130,92,.8)', 2, 0.55);
  audio.play('hurt');
  if (lives <= 0) {
    gameOver(cause);
  } else {
    respawn();
  }
  return true;
}

function respawn() {
  player.x = cpSpawn.x; player.y = cpSpawn.y;
  player.vx = 0; player.vy = 0;
  player.grounded = false; player.coyote = 0; player.jumpBuf = 0;
  player.wallDir = 0; player.wallJumps = 0; player.flowT = 0; player.wallFreshT = 0;
  player.dashT = 0; player.dashCd = 0; player.invulnT = 1.25;
  player.trail.length = 0;
  chi = Math.max(chi, 60);
  snapCamera();
  ui.toast(`命火复燃 · 还剩 ${lives} 命`, 1600);
}

// --- input ----------------------------------------------------------------
function processMeta() {
  if (pressed.has('KeyM')) {
    pressed.delete('KeyM');
    toggleMute();
  }
  if (pressed.has('KeyP')) {
    pressed.delete('KeyP');
    if (mode === 'play') togglePause();
  }
  if (pressed.has('KeyR')) {
    pressed.delete('KeyR');
    if (mode !== 'title') startGame();
  }
  if (mode === 'title' && (pressed.has('Space') || pressed.has('Enter'))) {
    pressed.delete('Space'); pressed.delete('Enter');
    startGame();
  } else if ((mode === 'over' || mode === 'win') && (pressed.has('Space') || pressed.has('Enter'))) {
    pressed.delete('Space'); pressed.delete('Enter');
    startGame();
  }
}

function press(...codes) {
  for (const c of codes) { held.add(c); pressed.add(c); }
}
function release(...codes) {
  for (const c of codes) held.delete(c);
}

window.addEventListener('keydown', (e) => {
  const c = e.code;
  if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(c)) e.preventDefault();
  if (e.repeat) return;
  if (!held.has(c)) pressed.add(c);
  held.add(c);
  if (!AUTOTEST) audio.unlock();
});
window.addEventListener('keyup', (e) => { held.delete(e.code); });
window.addEventListener('blur', () => {
  held.clear(); touch.left = touch.right = touch.jump = touch.dash = false;
});

function bindTouch(id, flag, onDown) {
  const el = document.getElementById(id);
  if (!el) return;
  const down = (e) => {
    if (e.cancelable) e.preventDefault();
    touch[flag] = true;
    if (onDown) onDown();
    el.classList.add('on');
    if (!AUTOTEST) audio.unlock();
    try { el.setPointerCapture(e.pointerId); } catch (err) { }
  };
  const up = (e) => {
    touch[flag] = false;
    el.classList.remove('on');
    if (e && e.cancelable) e.preventDefault();
  };
  el.addEventListener('pointerdown', down);
  el.addEventListener('pointerup', up);
  el.addEventListener('pointercancel', up);
  el.addEventListener('pointerleave', (e) => { if (e.pointerType === 'touch') up(e); });
}
bindTouch('btn-left', 'left');
bindTouch('btn-right', 'right');
bindTouch('btn-jump', 'jump', () => pressed.add('Space'));
bindTouch('btn-dash', 'dash', () => pressed.add('ShiftLeft'));

document.addEventListener('visibilitychange', () => {
  if (document.hidden && mode === 'play' && !paused) togglePause(true);
});

// --- physics --------------------------------------------------------------
function tryDash(dir) {
  if (player.dashT > 0) return false;
  if (player.dashCd > 0) return false;
  if (chi < DASH_COST) {
    audio.play('dashNo');
    floatText(player.x, player.y + 1.7, '气不足', '#d99a82');
    return false;
  }
  const dd = dir || player.face;
  player.dashDir = dd;
  player.face = dd;
  player.dashT = DASH_TIME;
  player.dashCd = DASH_CD;
  player.invulnT = Math.max(player.invulnT, DASH_IFRAME);
  player.vy = 0;
  player.vx = dd * DASH_SPEED;
  chi = Math.max(0, chi - DASH_COST);
  if (player.wallFreshT > 0) {
    player.wallFreshT = 0;
    score += WALL_DASH_BONUS;
    chi = Math.min(MAX_CHI, chi + 10);
    ui.banner('蹬墙 · 疾影', `+${WALL_DASH_BONUS} 分 · 气 +10`, 1200);
    floatText(player.x, player.y + 2.0, `+${WALL_DASH_BONUS}`, '#ffe38f');
    burst(player.x, player.y + 0.85, 16, ['#ffe3a0', '#c84e3b', '#9fe8c8'], 8, { size: 2.2, life: 0.7 });
    audio.play('wallDash');
    addShake(3);
  } else {
    audio.play('dash');
  }
  for (let i = 0; i < 10; i++) {
    spawnParticle(player.x - dd * 0.3, player.y + rnd(0.2, 1.4), -dd * rnd(3, 9), rnd(-2, 2), 'spark', i % 2 ? '#ffe0a0' : '#c84e3b', rnd(0.25, 0.5), 1.2 + Math.random(), { grav: -2 });
  }
  return true;
}

function updatePlayer(dt) {
  const p = player;
  const wasGrounded = p.grounded;
  const prevVy = p.vy;

  p.dashCd = Math.max(0, p.dashCd - dt);
  p.dashT = Math.max(0, p.dashT - dt);
  p.invulnT = Math.max(0, p.invulnT - dt);
  p.flowT = Math.max(0, p.flowT - dt);
  p.wallFreshT = Math.max(0, p.wallFreshT - dt);
  p.coyote = Math.max(0, p.coyote - dt);

  const left = isLeft(), right = isRight();
  const dir = (right ? 1 : 0) - (left ? 1 : 0);
  if (dir) p.face = dir;

  if (isJumpDown()) p.jumpBuf = JUMP_BUFFER;
  else p.jumpBuf = Math.max(0, p.jumpBuf - dt);

  if (isDashDown()) tryDash(dir);

  if (p.dashT > 0) {
    p.vx = p.dashDir * DASH_SPEED;
    p.vy = 0;
    ghostAcc += dt;
    if (ghostAcc > 0.032) {
      ghostAcc = 0;
      ghosts.push({ x: p.x, y: p.y, life: 1, rot: 0.25 * p.dashDir });
    }
  } else {
    // jump order: ground/coyote first, then wall
    if (p.jumpBuf > 0 && (p.grounded || p.coyote > 0)) {
      p.vy = JUMP_V;
      p.grounded = false;
      p.coyote = 0;
      p.jumpBuf = 0;
      p.wallJumps = 0;
      audio.play('jump');
      burst(p.x, p.y, 8, ['#e6c98e', '#a9774c', '#f5dfb0'], 4, { size: 1.5, life: 0.4, up: 1, type: 'dust' });
      ring(p.x, p.y, 'rgba(255,224,164,.5)', 1.4, 0.3);
    } else if (p.jumpBuf > 0 && p.wallDir !== 0 && !p.grounded) {
      const away = -p.wallDir;
      p.vx = away * WALL_JUMP_X;
      p.vy = WALL_JUMP_Y;
      p.face = away;
      p.grounded = false;
      p.coyote = 0;
      p.jumpBuf = 0;
      p.wallJumps++;
      p.wallFreshT = 1.5;
      audio.play('wall');
      const wvx = p.wallDir * 4;
      burst(p.x - p.wallDir * 0.35, p.y + 1.1, 10, ['#ffe0a0', '#9fe8c8', '#c84e3b'], 5, { size: 1.6, life: 0.46, up: 1 });
      addShake(1.5);
      if (p.wallJumps >= 3) {
        p.wallJumps = 0;
        p.flowT = FLOW_TIME;
        score += FLOW_BONUS;
        hitstop = Math.max(hitstop, HITSTOP_FLOW);
        addShake(5);
        flashT = Math.max(flashT, 0.12);
        audio.play('flow');
        ui.banner('流 · 蹬墙三连', `疾行加速 ${FLOW_TIME.toFixed(0)} 秒 · +${FLOW_BONUS} 分`, 1800);
        floatText(p.x, p.y + 2.2, `+${FLOW_BONUS}`, '#ffe58f');
        ring(p.x, p.y + 0.8, 'rgba(255,225,150,.9)', 2.5, 0.7);
        burst(p.x, p.y + 0.8, 18, ['#ffe8a8', '#9fe8c8'], 7, { size: 2.1, life: 0.7 });
      }
      if (!hintWall && runT < 12) {
        hintWall = true;
        ui.toast('漂亮的蹬墙！趁气未散按 Shift 冲刺', 2600);
      }
    }
    // horizontal control
    if (dir) {
      const target = dir * MOVE * (p.flowT > 0 ? FLOW_MULT : 1);
      p.vx = approach(p.vx, target, (p.grounded ? GROUND_ACC : AIR_ACC) * dt);
    } else {
      p.vx = approach(p.vx, 0, (p.grounded ? GROUND_FRICTION : AIR_DRAG) * dt);
    }
    // gravity and variable jump
    if (!p.grounded) {
      p.vy -= GRAV * dt;
      if (!isJumpHeld() && p.vy > 0) p.vy -= GRAV * 0.95 * dt;
      p.vy = Math.max(MAX_FALL, p.vy);
    } else if (p.vy < 0) {
      p.vy = 0;
    }
    // wall slide
    if (!p.grounded && p.wallDir !== 0 && p.vy < 0 && dir === p.wallDir) {
      p.vy = Math.max(p.vy, -WALL_SLIDE);
      if (Math.random() < dt * 26) {
        spawnParticle(p.x + p.wallDir * HALF_W, p.y + rnd(0.2, 1.4), -p.wallDir * rnd(0.5, 2.2), rnd(-2.5, -0.6), 'spark', '#e8c78d', rnd(0.2, 0.45), 1.1, { grav: 2 });
      }
    }
  }

  // integrate horizontal + wall collision
  p.x += p.vx * dt;
  p.x = clamp(p.x, HALF_W, WORLD_W - HALF_W);
  for (const w of level.walls) {
    if (p.x + HALF_W <= w.x || p.x - HALF_W >= w.x + w.w || p.y >= w.y + w.h || p.y + PH <= w.y) continue;
    if (p.vx > 0) p.x = w.x - HALF_W;
    else if (p.vx < 0) p.x = w.x + w.w + HALF_W;
    else {
      const dL = Math.abs(p.x - HALF_W - (w.x + w.w));
      const dR = Math.abs(p.x + HALF_W - w.x);
      if (dL < dR) p.x = w.x + w.w + HALF_W;
      else p.x = w.x - HALF_W;
    }
    p.vx = 0;
  }

  // integrate vertical + one-way landings
  const oldY = p.y;
  if (p.dashT <= 0) p.y += p.vy * dt;
  p.grounded = false;
  if (p.vy <= 0 || p.dashT <= 0) {
    let landY = -Infinity;
    for (const s of level.platforms) {
      if (p.x + HALF_W <= s.x + 0.01 || p.x - HALF_W >= s.x + s.w - 0.01) continue;
      if (oldY >= s.y - 0.015 && p.y <= s.y + 0.015 && s.y > landY) landY = s.y;
    }
    for (const w of level.walls) {
      const top = w.y + w.h;
      if (p.x + HALF_W <= w.x + 0.01 || p.x - HALF_W >= w.x + w.w - 0.01) continue;
      if (oldY >= top - 0.015 && p.y <= top + 0.015 && top > landY) landY = top;
    }
    if (landY > -Infinity) {
      p.y = landY;
      p.vy = 0;
      p.grounded = true;
    }
  }

  // wall probe after movement
  p.wallDir = 0;
  if (!p.grounded) {
    for (const w of level.walls) {
      if (p.y >= w.y + w.h || p.y + PH <= w.y) continue;
      if (Math.abs((p.x - HALF_W) - (w.x + w.w)) < 0.16 && p.x > w.x + w.w * 0.5) { p.wallDir = -1; break; }
      if (Math.abs((p.x + HALF_W) - w.x) < 0.16 && p.x < w.x + w.w * 0.5) { p.wallDir = 1; break; }
    }
  }

  if (p.grounded) {
    p.wallJumps = 0;
    p.coyote = COYOTE;
    if (!wasGrounded && prevVy < -7) {
      audio.play('land');
      burst(p.x, p.y, 6, ['#d8b27f', '#8c6a52'], 3, { size: 1.4, life: 0.35, type: 'dust', up: 0 });
      addShake(Math.min(2.5, -prevVy * 0.11));
    }
    if (Math.abs(p.vx) > 4 && Math.random() < dt * 12) {
      dustAcc += dt;
      if (dustAcc > 0.1) {
        dustAcc = 0;
        spawnParticle(p.x - p.face * 0.25, p.y + 0.05, -p.face * rnd(1, 3), rnd(0.2, 1.4), 'dust', 'rgba(214,174,122,.55)', rnd(0.25, 0.45), rnd(1, 2), { grav: -1 });
      }
    }
  }

  // trail
  trailAcc += dt;
  if (trailAcc > 0.035) {
    trailAcc = 0;
    p.trail.push({ x: p.x - p.face * 0.12, y: p.y + 1.42 });
    if (p.trail.length > 11) p.trail.shift();
  }

  // teach the first wall-dash inside the first ten seconds
  if (!hintDash && p.wallFreshT > 0 && runT < 10) {
    hintDash = true;
    ui.toast('趁蹬墙后的 1.5 秒按 Shift，疾影会额外加分', 2600);
  }
}

// --- interactions ---------------------------------------------------------
function updateHazards(dt) {
  for (const h of level.hazards) {
    if (h.static) { h.active = true; h.warn = false; continue; }
    const local = (runT + h.phase) % h.cycle;
    h.warn = local < h.warnDur;
    h.active = local >= h.warnDur && local < h.warnDur + h.activeDur;
  }
  if (player.invulnT > 0) return;
  for (const h of level.hazards) {
    if (!h.active) continue;
    if (player.x + HALF_W > h.x && player.x - HALF_W < h.x + h.w &&
      player.y < h.y + h.h && player.y + PH > h.y) {
      damage('刺阵');
      return;
    }
  }
}

function updatePickups() {
  const cx = player.x, cy = player.y + 0.86;
  for (const p of level.pickups) {
    if (p.taken) continue;
    const dx = cx - p.x, dy = cy - p.y;
    if (dx * dx + dy * dy < 0.82 * 0.82) {
      p.taken = true;
      dust++;
      chi = Math.min(MAX_CHI, chi + DUST_CHI);
      score += DUST_SCORE;
      audio.play('dust');
      burst(p.x, p.y, 12, ['#ffe7a6', '#f4bd62', '#fff5cf'], 5, { size: 1.8, life: 0.55, grav: -1 });
      ring(p.x, p.y, 'rgba(255,222,138,.75)', 1.2, 0.4);
      floatText(p.x, p.y + 0.7, `灯屑 +1 · 气 +${DUST_CHI}`, '#ffe7a6');
    }
  }
}

function checkProgress() {
  if (mode !== 'play') return;
  if (player.y > maxHeight) maxHeight = player.y;
  const fl = Math.floor(maxHeight);
  if (fl > lastScoredHeight) {
    score += (fl - lastScoredHeight) * HEIGHT_SCORE;
    lastScoredHeight = fl;
  }
  while (nextCpIndex <= CFG.CP_COUNT && player.y >= nextCpIndex * CFG.CP_STEP) {
    checkpointY = nextCpIndex * CFG.CP_STEP;
    cpSpawn = { x: 15, y: checkpointY + 0.03 };
    score += CP_BONUS;
    chi = MAX_CHI;
    nextCpIndex++;
    audio.play('checkpoint');
    addShake(2.5);
    flashT = Math.max(flashT, 0.1);
    ring(player.x, player.y + 0.8, 'rgba(151,240,207,.9)', 3, 0.8);
    burst(player.x, player.y + 0.8, 22, ['#b9f3d9', '#ffe2a1'], 7, { size: 2, life: 0.8 });
    ui.banner(`灯标 ${checkpointY}m`, `命火已记 · 气已回满 · +${CP_BONUS}`, 1900);
    report('progress', { score, progress: checkpointY });
    audio.setState(zoneNow().id);
  }
  if (player.y < checkpointY - 28) {
    damage('坠入深渊');
  }
  if (player.y >= WORLD_H) win();
}

// --- camera / fx ----------------------------------------------------------
function updateCamera(dt, snap = false) {
  const target = clamp(player.y - 17.8, -5, WORLD_H - 18);
  if (snap) cameraY = target;
  else cameraY += (target - cameraY) * (1 - Math.exp(-7.5 * dt));
  shakeAmp *= Math.exp(-6.2 * dt);
  if (shakeAmp < 0.04) shakeAmp = 0;
  flashT = Math.max(0, flashT - dt);
  if (hitstop > 0) hitstop = Math.max(0, hitstop - dt);
}

function updateFx(dt) {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.life -= dt;
    if (p.life <= 0) { particles.splice(i, 1); continue; }
    p.vy -= (p.grav || 0) * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.rot = (p.rot || 0) + dt * 5;
  }
  for (let i = floats.length - 1; i >= 0; i--) {
    const f = floats[i];
    f.life -= dt;
    f.y += dt * 1.15;
    if (f.life <= 0) floats.splice(i, 1);
  }
  for (let i = ghosts.length - 1; i >= 0; i--) {
    ghosts[i].life -= dt * 3.4;
    if (ghosts[i].life <= 0) ghosts.splice(i, 1);
  }
}

// --- main tick ------------------------------------------------------------
function tick(dt) {
  processMeta();
  if (mode !== 'play') { updateFx(dt); updateCamera(dt); clearPressed(); return; }
  if (paused) { updateFx(0); clearPressed(); return; }
  if (hitstop > 0) {
    hitstop = Math.max(0, hitstop - dt);
    updateFx(dt * 0.28);
    updateCamera(dt * 0.3);
    clearPressed();
    return;
  }
  runT += dt;
  checkProgress();
  if (mode !== 'play') { updateFx(dt); clearPressed(); return; }
  updatePlayer(dt);
  updatePickups();
  updateHazards(dt);
  if (mode === 'play') checkProgress();
  updateFx(dt);
  updateCamera(dt);
  if (mode === 'play') {
    const z = zoneNow();
    if (audio.state !== 'danger' && lives === 1) audio.setState('danger');
    else if (lives > 1 && audio.state === 'danger') audio.setState(z.id);
    else if (audio.state === 'title' || !audio.state) audio.setState(z.id);
  }
  clearPressed();
}

// --- render ---------------------------------------------------------------
let lastRenderT = 0;
function render(t) {
  lastRenderT = t;
  const zone = zoneNow();
  const z = zoneAt(clamp(player.y, 0, WORLD_H - 0.001));
  const shakeX = shakeAmp > 0 ? Math.sin(t * 88) * shakeAmp : 0;
  const shakeY = shakeAmp > 0 ? Math.cos(t * 73) * shakeAmp * 0.7 : 0;
  renderer.draw({
    t, mode, paused,
    cameraY, shakeX, shakeY,
    level, player, particles, floats, ghosts,
    checkpointY, flowT: player.flowT,
    flashT, runT,
    showPlayer: true,
  });
  ui.setHud({
    height: maxHeight,
    best,
    score: Math.floor(score),
    dust,
    lives,
    chi,
    maxChi: MAX_CHI,
    dashCd: player.dashCd,
    flowT: player.flowT,
    flowMult: player.flowT > 0 ? FLOW_MULT : 1,
    zone: z,
  });
}

// --- loop -----------------------------------------------------------------
let lastTs = performance.now();
let acc = 0;
function frame(ts) {
  requestAnimationFrame(frame);
  let dt = (ts - lastTs) / 1000;
  lastTs = ts;
  if (!Number.isFinite(dt) || dt < 0) dt = 0;
  dt = Math.min(dt, 0.05);
  if (!document.hidden) {
    if (mode === 'play' && !paused && !noAuto) {
      acc = Math.min(acc + dt, 0.16);
      let guard = 0;
      while (acc >= DT && guard++ < 6) { tick(DT); acc -= DT; }
    } else {
      processMeta();
      ambientT += dt;
      if (!paused) updateFx(dt);
      updateCamera(dt);
    }
  }
  audio.tick(dt);
  render(ts / 1000);
}

// --- boot -----------------------------------------------------------------
resetRun();
mode = 'title';
snapCamera();
ui.setBest(best);
loadMutedUI();
ui.showTitle(true);
ui.setHud({
  height: maxHeight, best, score, dust, lives, chi, maxChi: MAX_CHI,
  dashCd: 0, flowT: 0, flowMult: 1, zone: zoneAt(0),
});
audio.setState('title');
render(performance.now() / 1000);
requestAnimationFrame(frame);

if (AUTOSTART && !AUTOTEST) {
  startGame();
}

// --- G debug hooks --------------------------------------------------------
function stateSnapshot() {
  return {
    mode, paused, noAuto,
    x: player.x, y: player.y, height: player.y, maxHeight,
    vx: player.vx, vy: player.vy, face: player.face,
    grounded: player.grounded, wallDir: player.wallDir, wallJumps: player.wallJumps,
    flowT: player.flowT, flowMult: player.flowT > 0 ? FLOW_MULT : 1,
    wallFreshT: player.wallFreshT,
    dashT: player.dashT, dashCd: player.dashCd, invuln: player.invulnT,
    lives, score: Math.floor(score), dust, chi, checkpoint: checkpointY,
    best, runT, streakBroken: player.wallJumps,
    particles: particles.length, floats: floats.length,
    pickupsLeft: level.pickups.reduce((n, p) => n + (p.taken ? 0 : 1), 0),
    zone: zoneNow().id, route: levelRoute,
  };
}

const G = {
  err: __BOOTERR,
  W, H, PPM, WORLD_W, WORLD_H,
  step: (n = 60, dt = DT) => {
    for (let i = 0; i < n; i++) { tick(dt); render(performance.now() / 1000); }
  },
  upd: (n = 30, dt = DT) => { for (let i = 0; i < n; i++) tick(dt); },
  press,
  release,
  setNoAuto: (v) => { noAuto = !!v; },
  setReportTarget: (fn) => { reportTarget = typeof fn === 'function' ? fn : null; },
  state: stateSnapshot,
  setHeight: (y) => {
    player.y = clamp(Number(y) || 0, -10, WORLD_H);
    player.vx = player.vy = 0;
    player.grounded = false; player.coyote = 0; player.wallDir = 0;
    player.dashT = 0; player.dashCd = 0; player.trail.length = 0;
    snapCamera();
    return player.y;
  },
  setPos: (x, y) => {
    player.x = clamp(Number(x) || 0, HALF_W, WORLD_W - HALF_W);
    player.y = clamp(Number(y) || 0, -10, WORLD_H);
    player.vx = player.vy = 0;
    player.grounded = false; player.coyote = 0; player.wallDir = 0;
    player.dashT = 0; player.trail.length = 0;
    snapCamera();
    return { x: player.x, y: player.y };
  },
  setLives: (n) => { lives = clamp(n | 0, 0, 9); ui.setHud({ height: maxHeight, best, score, dust, lives, chi, maxChi: MAX_CHI, dashCd: player.dashCd, flowT: player.flowT, flowMult: player.flowT > 0 ? FLOW_MULT : 1, zone: zoneNow() }); },
  setChi: (n) => { chi = clamp(Number(n) || 0, 0, MAX_CHI); },
  setScore: (n) => { score = Math.max(0, Number(n) || 0); },
  setDust: (n) => { dust = Math.max(0, n | 0); },
  setBest: (n) => { best = Math.max(0, n | 0); ui.setBest(best); },
  setInvuln: (n) => { player.invulnT = Math.max(0, Number(n) || 0); },
  setPaused: (v) => { if (mode === 'play') { paused = !!v; ui.setPaused(paused); } },
  forceGameOver: () => { if (mode !== 'play') startGame(); lives = 0; gameOver('力竭'); },
  forceWin: () => { if (mode !== 'play') startGame(); win(); },
  damage: (cause) => damage(cause || '试炼'),
  startGame, toTitle, win, gameOver, report,
  level, route: levelRoute, audio, ui, renderer,
  audioState: () => audio.state,
  render: () => render(performance.now() / 1000),
};
window.G = G;
window.__G = G;

// --- autotest -------------------------------------------------------------
const nap = () => new Promise(r => {
  const mc = new MessageChannel();
  mc.port1.onmessage = () => r();
  mc.port2.postMessage(0);
});

const finite = v => typeof v === 'number' && Number.isFinite(v);

async function autotest() {
  G.setNoAuto(true);
  const results = [];
  const assert = (id, ok, name) => {
    results.push({ id, ok: !!ok, name });
    if (!ok) console.warn(`[autotest] FAIL T${id}: ${name}`);
  };
  const S = () => G.state();
  const savedBest = best;
  const savedStored = (() => { try { return localStorage.getItem('ssn.best'); } catch (e) { return null; } })();
  const frames = [];
  G.setReportTarget(f => frames.push(f));
  audio.setMuted(true, false);

  try {
    await nap();

    // T1 boot clean
    assert(1, G.err.length === 0 && (!window.__BOOTERR || window.__BOOTERR.length === 0), `启动零报错 errors=${G.err.length}`);

    // T2 short run stays finite
    startGame();
    G.press('KeyD', 'Space'); G.upd(20); G.release('KeyD', 'Space'); G.upd(60);
    const st2 = S();
    assert(2, ['x', 'y', 'vx', 'vy', 'height', 'score', 'chi', 'dashCd'].every(k => finite(st2[k])), '跑动 80 帧关键数值无 NaN');

    // T3 ground jump impulse
    startGame();
    const yj = S().height;
    G.press('Space'); G.upd(1); G.release('Space');
    assert(3, S().vy > 10 && S().height > yj, `跳跃上升 vy=${S().vy.toFixed(2)}`);

    // T4 wall-jump maths (real wall contact)
    startGame();
    G.setPos(1.58, 5.2); G.upd(1);
    const wallDetected = S().wallDir === -1;
    G.press('Space'); G.upd(1); G.release('Space');
    const st4 = S();
    assert(4, wallDetected && st4.vx > 5 && st4.vy > 10 && st4.wallJumps >= 1, `贴墙=${wallDetected} vx=${st4.vx.toFixed(1)} vy=${st4.vy.toFixed(1)} 连跳=${st4.wallJumps}`);

    // T5 dash cost / i-frames / cooldown
    startGame();
    G.setChi(100);
    G.press('KeyD', 'ShiftLeft'); G.upd(1); G.release('ShiftLeft', 'KeyD');
    const st5 = S();
    assert(5, st5.chi === 76 && st5.dashCd > 0.2 && st5.invuln > 0, `气 100→${st5.chi} cd=${st5.dashCd.toFixed(2)} i帧=${st5.invuln.toFixed(2)}`);

    // T6 dash rejection during cooldown
    G.press('ShiftLeft'); G.upd(1); G.release('ShiftLeft');
    assert(6, S().chi === 76, '冷却中的第二次冲刺不扣气');

    // T7 dash refusal when out of chi
    G.setChi(10); G.upd(36);
    G.press('ShiftLeft'); G.upd(1); G.release('ShiftLeft');
    assert(7, S().chi === 10 && S().dashT === 0, '气不足时冲刺被拒绝');

    // T8 three air wall-jumps → flow boost and score
    startGame();
    for (let i = 0; i < 3; i++) {
      G.setPos(i % 2 === 0 ? 1.58 : 28.42, 5.2 + i * 0.15);
      G.upd(1);
      G.press('Space'); G.upd(1); G.release('Space'); G.upd(1);
    }
    const st8 = S();
    assert(8, st8.flowT > 0 && st8.score >= FLOW_BONUS, `三连蹬墙 flowT=${st8.flowT.toFixed(2)} score=${st8.score}`);

    // T9 wall-jump + dash bonus (first ten seconds positive loop)
    startGame();
    G.setPos(1.58, 5.2); G.upd(1);
    G.press('Space'); G.upd(1); G.release('Space'); G.upd(1);
    const scoreBeforeDash = S().score;
    G.press('ShiftLeft'); G.upd(1); G.release('ShiftLeft');
    assert(9, S().score >= scoreBeforeDash + 100, `蹬墙后冲刺 +${S().score - scoreBeforeDash} 分`);

    // T10 checkpoint activation
    startGame();
    frames.length = 0;
    G.setHeight(150); G.upd(1);
    const st10 = S();
    assert(10, st10.checkpoint >= 150 && st10.chi === MAX_CHI && st10.score >= CP_BONUS, `灯标=${st10.checkpoint}m 气=${st10.chi} 分=${st10.score}`);

    // T11 progress report exists after checkpoint
    assert(11, frames.some(f => f.kind === 'progress' && f.progress >= 150), `progress 帧=${frames.map(f => f.kind).join(',')}`);

    // T12 damage costs a life and respawns at checkpoint
    G.setLives(3); G.setInvuln(0);
    const cp10 = S().checkpoint;
    G.damage('刺阵'); G.upd(2);
    const st12 = S();
    assert(12, st12.lives === 2 && st12.mode === 'play' && Math.abs(st12.y - cp10) < 2.5, `命 3→${st12.lives} 复活=${st12.y.toFixed(1)}m`);

    // T13 failure path: final life → gameOver report
    frames.length = 0;
    G.setInvuln(0); G.setLives(1);
    G.damage('最后一击'); G.upd(1);
    assert(13, S().mode === 'over' && frames.some(f => f.kind === 'gameOver'), `mode=${S().mode} 上报=${frames.map(f => f.kind).join(',')}`);

    // T14 victory path: crossing the summit reaches complete
    startGame(); frames.length = 0;
    G.setHeight(1200); G.upd(1);
    assert(14, S().mode === 'win' && frames.some(f => f.kind === 'complete' && f.progress === 1200), `mode=${S().mode} 上报=${frames.map(f => f.kind).join(',')}`);

    // T15 dust pickup economy
    startGame();
    const pk = level.pickups.find(p => !p.taken);
    G.setChi(40); G.setDust(0); G.setScore(0);
    G.setPos(pk.x, pk.y - 0.72); G.upd(1);
    const st15 = S();
    assert(15, st15.dust === 1 && st15.chi === 58 && st15.score >= DUST_SCORE, `灯屑=${st15.dust} 气=${st15.chi} 分=${st15.score}`);

    // T16 height pays score
    startGame();
    const s16 = S().score;
    G.setHeight(20); G.upd(1);
    assert(16, S().score > s16 + 20, `爬升加分 ${s16}→${S().score}`);

    // T17 simulated input moves the body
    startGame();
    const x17 = S().x;
    G.press('KeyD'); G.upd(30); G.release('KeyD');
    assert(17, S().x > x17 + 1, `按 D 30 帧 x ${x17.toFixed(2)}→${S().x.toFixed(2)}`);

    // T18 jump input raises height
    startGame();
    const h18 = S().height;
    G.press('Space'); G.upd(12); G.release('Space');
    assert(18, S().height > h18 + 0.7, `空格后高度 ${h18.toFixed(2)}→${S().height.toFixed(2)}`);

    // T19 pause freezes, resume moves
    startGame();
    G.press('KeyD'); G.upd(6);
    G.press('KeyP'); G.upd(1);
    const xPause = S().x;
    G.upd(30);
    const pausedX = S().x;
    G.press('KeyP'); G.upd(1); G.upd(10); G.release('KeyD');
    assert(19, S().paused === false && Math.abs(pausedX - xPause) < 0.001 && S().x > pausedX + 0.2, `暂停冻结 x=${pausedX.toFixed(2)} 恢复后=${S().x.toFixed(2)}`);

    // T20 touch bindings exist and jump button works
    startGame();
    const h20 = S().height;
    const touchIds = ['btn-left', 'btn-right', 'btn-jump', 'btn-dash'];
    const touchOk = touchIds.every(id => !!document.getElementById(id));
    const jumpBtn = document.getElementById('btn-jump');
    jumpBtn.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerType: 'touch' }));
    G.upd(2);
    jumpBtn.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, pointerType: 'touch' }));
    assert(20, touchOk && S().height > h20, `触控键=${touchOk} 跳后高度=${S().height.toFixed(2)}`);

    // T21 restart resets the run
    startGame();
    G.setScore(999); G.setDust(5); G.setHeight(300); G.forceGameOver();
    startGame();
    const st21 = S();
    assert(21, st21.lives === 3 && st21.score === 0 && st21.dust === 0 && st21.mode === 'play' && st21.height < 5, `重开 lives=${st21.lives} score=${st21.score} h=${st21.height.toFixed(1)}`);

    // T22 best height persists and can be restored
    try { localStorage.setItem('ssn.best', '0'); } catch (e) { }
    G.setBest(0);
    startGame(); G.setHeight(432); G.upd(1); G.forceGameOver();
    let stored = 0;
    try { stored = parseInt(localStorage.getItem('ssn.best') || '0', 10) || 0; } catch (e) { }
    assert(22, stored >= 432 && S().best >= 432, `localStorage=${stored} state.best=${S().best}`);

    // T23 ready is the first report frame
    assert(23, reports[0] && reports[0].kind === 'ready', `首帧=${reports[0] && reports[0].kind}`);

    // T24 progress → gameOver order
    startGame(); frames.length = 0;
    G.setHeight(150); G.upd(1); G.forceGameOver();
    const kinds24 = frames.map(f => f.kind);
    assert(24, kinds24.indexOf('progress') >= 0 && kinds24.indexOf('progress') < kinds24.indexOf('gameOver') && kinds24[kinds24.length - 1] === 'gameOver', `帧序=${kinds24.join('→')}`);

    // T25 progress → complete order and integer payload
    startGame(); frames.length = 0;
    G.setHeight(1200); G.upd(1);
    const kinds25 = frames.map(f => f.kind);
    const last25 = frames[frames.length - 1];
    assert(25, kinds25.includes('complete') && Number.isInteger(last25.score) && Number.isInteger(last25.progress), `帧序=${kinds25.join('→')}`);

    // T26 level route continuity
    assert(26, levelRoute.count > 350 && levelRoute.maxDy <= 3.05 && levelRoute.maxEdgeGap <= 7.0 && levelRoute.top >= 1199, `路线 ${levelRoute.count} 台 最大升差 ${levelRoute.maxDy.toFixed(2)}m 最大横距 ${levelRoute.maxEdgeGap.toFixed(2)}m`);

    // T27 full fast-forward with random input, no NaN / new errors
    startGame();
    const errBefore = G.err.length;
    const codes = ['KeyA', 'KeyD', 'Space', 'ShiftLeft', 'Space'];
    for (let i = 0; i < 1200; i++) {
      if (i % 23 === 0) G.release('KeyA', 'KeyD', 'ShiftLeft');
      if (i % 31 === 0) G.press(codes[(i / 31 | 0) % codes.length]);
      G.upd(1);
    }
    G.release('KeyA', 'KeyD', 'Space', 'ShiftLeft');
    const st27 = S();
    const finite27 = Object.values(st27).filter(v => typeof v === 'number').every(Number.isFinite);
    assert(27, finite27 && G.err.length === errBefore, `1200 帧快进 finite=${finite27} err+${G.err.length - errBefore}`);

    // T28 render path advances without errors
    const errBefore28 = G.err.length;
    G.step(8);
    assert(28, G.err.length === errBefore28, 'step 渲染 8 帧零新增错误');

    // T29 muted by default in autotest
    assert(29, audio.muted === true, '自测默认静音');

    // T30 static bridge aliases
    assert(30, typeof window.goHome === 'function' && typeof window.clickMore === 'function' && typeof window.dp_share === 'function' && typeof window.play68_init === 'function', 'play68 桥接别名存在');

    // T31 title screen has best + series imprint + one-line how-to
    toTitle();
    const titleTxt = document.getElementById('title').textContent || '';
    const bestTxt = document.getElementById('titlebest').textContent || '';
    assert(31, /灯匠夜游/.test(titleTxt) && /2/.test(titleTxt) && /最高|尚无/.test(bestTxt), `标题 best="${bestTxt}"`);

    // T32 back to title and no active run
    assert(32, S().mode === 'title' && !document.getElementById('title').classList.contains('hide'), `mode=${S().mode}`);

    // restore the player's own best record after all destructive tests
    try {
      if (savedStored == null) localStorage.removeItem('ssn.best');
      else localStorage.setItem('ssn.best', savedStored);
    } catch (e) { }
    G.setBest(savedBest);
    audio.setMuted(true, false);
    ui.setMuted(true);
    G.setReportTarget(null);
  } catch (err) {
    window.__TEST_ERR = String(err && err.stack || err);
    console.error('[autotest] crashed:', window.__TEST_ERR);
    const pass = results.filter(r => r.ok).length;
    window.__TEST = { pass, fail: results.length - pass + 1, total: results.length + 1, passed: pass, failed: results.length - pass + 1, results, done: true, crashed: true };
    return;
  }

  const pass = results.filter(r => r.ok).length;
  const fail = results.length - pass;
  window.__TEST = {
    pass, fail, total: results.length,
    passed: pass, failed: fail,
    results, done: true,
  };
  console.log(`[autotest] ${pass}/${results.length} passed`);
}

if (AUTOTEST) autotest();

toolUseResult.content:
// Shadowspire Ninja 影峰登天 — a vertical wall-jump tower climb.
// Vanilla ES module, fixed-step physics, procedural canvas art, WebAudio synth,
// site report bridge, debug G hooks and a deterministic ?autotest=1 suite.

import { CFG, zoneAt, buildLevel, surfaceBelow, routeStats } from './level.js';
import { makeAudio } from './audio.js';
import { makeUI } from './ui.js';
import { createRenderer } from './render.js';

const DT = 1 / 60;
const W = CFG.W, H = CFG.H, PPM = CFG.PPM;
const WORLD_W = CFG.WORLD_W, WORLD_H = CFG.WORLD_H;
const PARAMS = new URLSearchParams(location.search);
const AUTOTEST = PARAMS.has('autotest');
const AUTOSTART = PARAMS.get('autostart') === '1' || PARAMS.has('auto');

// --- feel / balance table -------------------------------------------------
const GRAV = 47;
const MAX_FALL = -22;
const MOVE = 7.7;
const GROUND_ACC = 58;
const AIR_ACC = 31;
const GROUND_FRICTION = 55;
const AIR_DRAG = 10;
const JUMP_V = 19.6;
const COYOTE = 0.11;
const JUMP_BUFFER = 0.12;
const WALL_SLIDE = 4.3;
const WALL_JUMP_X = 9.4;
const WALL_JUMP_Y = 17.7;
const MAX_CHI = 100;
const DASH_COST = 24;
const DASH_SPEED = 27;
const DASH_TIME = 0.16;
const DASH_CD = 0.38;
const DASH_IFRAME = 0.23;
const HITSTOP_DEATH = 0.085;
const HITSTOP_FLOW = 0.07;
const FLOW_TIME = 3.2;
const FLOW_MULT = 1.28;
const FLOW_BONUS = 200;
const WALL_DASH_BONUS = 120;
const DUST_CHI = 18;
const DUST_SCORE = 25;
const HEIGHT_SCORE = 2;
const CP_BONUS = 300;
const START_LIVES = 3;
const PW = 0.78, PH = 1.72;
const HALF_W = PW / 2;

const __BOOTERR = window.__BOOTERR || (window.__BOOTERR = []);

// --- modules --------------------------------------------------------------
const canvas = document.getElementById('cv');
const renderer = createRenderer(canvas);
const level = buildLevel();
const audio = makeAudio({ autotest: AUTOTEST });
const levelRoute = routeStats(level);

let reportTarget = null;
const reports = [];
function report(kind, payload = {}) {
  const frame = { kind, ...payload };
  if (frame.score != null) frame.score = Math.round(frame.score);
  if (frame.progress != null) frame.progress = Math.round(frame.progress);
  reports.push(frame);
  try {
    if (reportTarget) reportTarget(frame);
    else if (window.parent !== window) {
      window.parent.postMessage(
        { source: 'lightgame', type: 'lightgame:report', payload: frame }, '*'
      );
    }
  } catch (e) { }
}
report('ready', { game: 'shadowspire-ninja' });

// --- state ----------------------------------------------------------------
let mode = 'title';             // title | play | over | win
let paused = false;
let noAuto = false;
let lives = START_LIVES;
let score = 0;
let dust = 0;
let chi = MAX_CHI;
let best = 0;
try { best = Math.max(0, parseInt(localStorage.getItem('ssn.best') || '0', 10) || 0); } catch (e) { }

let maxHeight = CFG.START_Y;
let lastScoredHeight = 0;
let checkpointY = 0;
let nextCpIndex = 1;
let cpSpawn = { x: 15, y: CFG.START_Y + 0.02 };
let runT = 0;
let ambientT = 0;
let endCause = '';
let hitstop = 0;
let shakeAmp = 0;
let flashT = 0;
let hintWall = false;
let hintDash = false;
let trailAcc = 0, ghostAcc = 0, dustAcc = 0;
let cameraY = -5;

const held = new Set();
const pressed = new Set();
const touch = { left: false, right: false, jump: false, dash: false };

const player = {
  x: 15, y: CFG.START_Y + 0.02, vx: 0, vy: 0, face: 1,
  grounded: true, coyote: 0, jumpBuf: 0, wallDir: 0,
  wallJumps: 0, flowT: 0, wallFreshT: 0,
  dashT: 0, dashCd: 0, dashDir: 1, invulnT: 0,
  trail: [],
};

const particles = [];
const floats = [];
const ghosts = [];

const ui = makeUI({
  onStart: () => { audio.unlock(); startGame(); },
  onRestart: () => { audio.unlock(); startGame(); },
  onBackTitle: () => { audio.play('ui'); toTitle(); },
  onMute: () => toggleMute(),
  onPause: () => togglePause(),
  onShare: () => {
    try {
      if (typeof window.dp_share === 'function') window.dp_share(Math.floor(maxHeight));
    } catch (e) { }
  },
});

// --- little helpers -------------------------------------------------------
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const approach = (v, target, delta) => v < target ? Math.min(target, v + delta) : Math.max(target, v - delta);
const rnd = (a, b) => a + Math.random() * (b - a);
const isJumpDown = () => pressed.has('Space') || pressed.has('KeyW') || pressed.has('ArrowUp');
const isJumpHeld = () => held.has('Space') || held.has('KeyW') || held.has('ArrowUp') || touch.jump;
const isDashDown = () => pressed.has('ShiftLeft') || pressed.has('ShiftRight') || pressed.has('KeyK');
const isLeft = () => held.has('KeyA') || held.has('ArrowLeft') || touch.left;
const isRight = () => held.has('KeyD') || held.has('ArrowRight') || touch.right;

function zoneNow() { return zoneAt(Math.max(0, Math.min(WORLD_H - 0.01, player.y))); }

function addShake(n) { shakeAmp = Math.min(8, shakeAmp + n); }
function addHitstop(n) { hitstop = Math.max(hitstop, n); }

function spawnParticle(x, y, vx, vy, type, color, life, size, extra = {}) {
  if (particles.length > 260) particles.shift();
  particles.push({ x, y, vx, vy, type, color, life, max: life, size, grav: 0, rot: 0, ...extra });
}
function burst(x, y, n, colors, spd = 6, opts = {}) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = spd * (0.32 + Math.random() * 0.85);
    spawnParticle(
      x, y, Math.cos(a) * s, Math.sin(a) * s + (opts.up || 0),
      opts.type || 'spark', colors[(Math.random() * colors.length) | 0],
      (opts.life || 0.55) * (0.6 + Math.random() * 0.7),
      (opts.size || 2) * (0.7 + Math.random() * 0.8),
      { grav: opts.grav == null ? 8 : opts.grav }
    );
  }
}
function ring(x, y, color, size = 2, life = 0.42) {
  spawnParticle(x, y, 0, 0, 'ring', color, life, size, { grav: 0 });
}
function floatText(x, y, text, color = '#ffe5a8') {
  if (floats.length > 16) floats.shift();
  floats.push({ x, y, text, color, life: 0.95, max: 0.95 });
}

function clearPressed() { pressed.clear(); }

function loadMutedUI() { ui.setMuted(audio.muted); }

// --- flow / reset ---------------------------------------------------------
function resetPickupsAndHazards() {
  for (const p of level.pickups) p.taken = false;
  for (const h of level.hazards) {
    if (!h.static) { h.active = false; h.warn = false; }
    else { h.active = true; h.warn = false; }
  }
}

function resetPlayer() {
  player.x = 15; player.y = CFG.START_Y + 0.02;
  player.vx = 0; player.vy = 0; player.face = 1;
  player.grounded = true; player.coyote = COYOTE; player.jumpBuf = 0; player.wallDir = 0;
  player.wallJumps = 0; player.flowT = 0; player.wallFreshT = 0;
  player.dashT = 0; player.dashCd = 0; player.dashDir = 1; player.invulnT = 0;
  player.trail.length = 0;
}

function resetRun() {
  lives = START_LIVES;
  score = 0; dust = 0; chi = MAX_CHI;
  maxHeight = CFG.START_Y; lastScoredHeight = Math.floor(CFG.START_Y);
  checkpointY = 0; nextCpIndex = 1;
  cpSpawn = { x: 15, y: CFG.START_Y + 0.02 };
  runT = 0; hitstop = 0; shakeAmp = 0; flashT = 0;
  hintWall = false; hintDash = false;
  trailAcc = 0; ghostAcc = 0; dustAcc = 0;
  particles.length = 0; floats.length = 0; ghosts.length = 0;
  resetPickupsAndHazards();
  resetPlayer();
}

function snapCamera() {
  cameraY = clamp(player.y - 17.8, -5, WORLD_H - 18);
}

function startGame() {
  resetRun();
  mode = 'play'; paused = false; endCause = '';
  snapCamera();
  ui.showTitle(false); ui.hideEnd(); ui.showPause(false); ui.setPaused(false);
  ui.setBest(best);
  audio.setState(zoneNow().id);
  ui.toast('A/D 横移 · 空格起跃 · 贴墙再按空格蹬墙 · Shift 冲刺', 4600);
  report('progress', { score: 0, progress: 0 });
}

function toTitle() {
  resetRun();
  mode = 'title'; paused = false;
  snapCamera();
  ui.showTitle(true); ui.hideEnd(); ui.showPause(false); ui.setPaused(false);
  ui.setBest(best);
  audio.setState('title');
}

function togglePause(force) {
  if (mode !== 'play') return;
  paused = force == null ? !paused : !!force;
  ui.setPaused(paused);
  if (paused) {
    ui.toast('入定 · P 继续', 1200);
    audio.setState('title');
  } else {
    audio.setState(zoneNow().id);
  }
}

function toggleMute() {
  audio.toggleMute();
  ui.setMuted(audio.muted);
  ui.toast(audio.muted ? '已静音 · M 恢复' : '声音已开 · M 静音', 1200);
}

function saveBest() {
  const h = Math.max(0, Math.floor(maxHeight));
  if (h > best) {
    best = h;
    try { localStorage.setItem('ssn.best', String(best)); } catch (e) { }
    ui.setBest(best);
    return true;
  }
  return false;
}

function gameOver(cause = '灯焰熄灭') {
  if (mode !== 'play') {
    if (mode === 'over') return;
  }
  endCause = cause;
  mode = 'over'; paused = false;
  saveBest();
  ui.setPaused(false);
  ui.showPause(false);
  report('gameOver', { score, progress: Math.floor(maxHeight), cause });
  audio.setState('title');
  audio.play('over');
  ui.showEnd({ kind: 'over', score: Math.floor(score), height: Math.floor(maxHeight), best, time: runT, cause });
}

function win() {
  if (mode !== 'play') return;
  mode = 'win'; paused = false;
  maxHeight = WORLD_H;
  score += 1000;
  saveBest();
  ui.setPaused(false);
  ui.showPause(false);
  report('complete', { score, progress: WORLD_H });
  audio.setState('win');
  audio.play('win');
  burst(player.x, player.y + 1, 42, ['#fff0b5', '#e4c06f', '#9fe8c8', '#c84e3b'], 10, { size: 2.4, life: 1.4, up: 4 });
  ui.showEnd({ kind: 'win', score: Math.floor(score), height: WORLD_H, best, time: runT });
}

function damage(cause = '刺阵') {
  if (mode !== 'play' || player.invulnT > 0) return false;
  lives--;
  endCause = cause;
  hitstop = HITSTOP_DEATH;
  addShake(7);
  flashT = 0.3;
  burst(player.x, player.y + 0.8, 24, ['#d9493a', '#f3a45f', '#ffe0a8'], 8, { size: 2.8, life: 0.7, up: 2 });
  ring(player.x, player.y + 0.8, 'rgba(255,130,92,.8)', 2, 0.55);
  audio.play('hurt');
  if (lives <= 0) {
    gameOver(cause);
  } else {
    respawn();
  }
  return true;
}

function respawn() {
  player.x = cpSpawn.x; player.y = cpSpawn.y;
  player.vx = 0; player.vy = 0;
  player.grounded = false; player.coyote = 0; player.jumpBuf = 0;
  player.wallDir = 0; player.wallJumps = 0; player.flowT = 0; player.wallFreshT = 0;
  player.dashT = 0; player.dashCd = 0; player.invulnT = 1.25;
  player.trail.length = 0;
  chi = Math.max(chi, 60);
  snapCamera();
  ui.toast(`命火复燃 · 还剩 ${lives} 命`, 1600);
}

// --- input ----------------------------------------------------------------
function processMeta() {
  if (pressed.has('KeyM')) {
    pressed.delete('KeyM');
    toggleMute();
  }
  if (pressed.has('KeyP')) {
    pressed.delete('KeyP');
    if (mode === 'play') togglePause();
  }
  if (pressed.has('KeyR')) {
    pressed.delete('KeyR');
    if (mode !== 'title') startGame();
  }
  if (mode === 'title' && (pressed.has('Space') || pressed.has('Enter'))) {
    pressed.delete('Space'); pressed.delete('Enter');
    startGame();
  } else if ((mode === 'over' || mode === 'win') && (pressed.has('Space') || pressed.has('Enter'))) {
    pressed.delete('Space'); pressed.delete('Enter');
    startGame();
  }
}

function press(...codes) {
  for (const c of codes) { held.add(c); pressed.add(c); }
}
function release(...codes) {
  for (const c of codes) held.delete(c);
}

window.addEventListener('keydown', (e) => {
  const c = e.code;
  if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(c)) e.preventDefault();
  if (e.repeat) return;
  if (!held.has(c)) pressed.add(c);
  held.add(c);
  if (!AUTOTEST) audio.unlock();
});
window.addEventListener('keyup', (e) => { held.delete(e.code); });
window.addEventListener('blur', () => {
  held.clear(); touch.left = touch.right = touch.jump = touch.dash = false;
});

function bindTouch(id, flag, onDown) {
  const el = document.getElementById(id);
  if (!el) return;
  const down = (e) => {
    if (e.cancelable) e.preventDefault();
    touch[flag] = true;
    if (onDown) onDown();
    el.classList.add('on');
    if (!AUTOTEST) audio.unlock();
    try { el.setPointerCapture(e.pointerId); } catch (err) { }
  };
  const up = (e) => {
    touch[flag] = false;
    el.classList.remove('on');
    if (e && e.cancelable) e.preventDefault();
  };
  el.addEventListener('pointerdown', down);
  el.addEventListener('pointerup', up);
  el.addEventListener('pointercancel', up);
  el.addEventListener('pointerleave', (e) => { if (e.pointerType === 'touch') up(e); });
}
bindTouch('btn-left', 'left');
bindTouch('btn-right', 'right');
bindTouch('btn-jump', 'jump', () => pressed.add('Space'));
bindTouch('btn-dash', 'dash', () => pressed.add('ShiftLeft'));

document.addEventListener('visibilitychange', () => {
  if (document.hidden && mode === 'play' && !paused) togglePause(true);
});

// --- physics --------------------------------------------------------------
function tryDash(dir) {
  if (player.dashT > 0) return false;
  if (player.dashCd > 0) return false;
  if (chi < DASH_COST) {
    audio.play('dashNo');
    floatText(player.x, player.y + 1.7, '气不足', '#d99a82');
    return false;
  }
  const dd = dir || player.face;
  player.dashDir = dd;
  player.face = dd;
  player.dashT = DASH_TIME;
  player.dashCd = DASH_CD;
  player.invulnT = Math.max(player.invulnT, DASH_IFRAME);
  player.vy = 0;
  player.vx = dd * DASH_SPEED;
  chi = Math.max(0, chi - DASH_COST);
  if (player.wallFreshT > 0) {
    player.wallFreshT = 0;
    score += WALL_DASH_BONUS;
    chi = Math.min(MAX_CHI, chi + 10);
    ui.banner('蹬墙 · 疾影', `+${WALL_DASH_BONUS} 分 · 气 +10`, 1200);
    floatText(player.x, player.y + 2.0, `+${WALL_DASH_BONUS}`, '#ffe38f');
    burst(player.x, player.y + 0.85, 16, ['#ffe3a0', '#c84e3b', '#9fe8c8'], 8, { size: 2.2, life: 0.7 });
    audio.play('wallDash');
    addShake(3);
  } else {
    audio.play('dash');
  }
  for (let i = 0; i < 10; i++) {
    spawnParticle(player.x - dd * 0.3, player.y + rnd(0.2, 1.4), -dd * rnd(3, 9), rnd(-2, 2), 'spark', i % 2 ? '#ffe0a0' : '#c84e3b', rnd(0.25, 0.5), 1.2 + Math.random(), { grav: -2 });
  }
  return true;
}

function updatePlayer(dt) {
  const p = player;
  const wasGrounded = p.grounded;
  const prevVy = p.vy;

  p.dashCd = Math.max(0, p.dashCd - dt);
  p.dashT = Math.max(0, p.dashT - dt);
  p.invulnT = Math.max(0, p.invulnT - dt);
  p.flowT = Math.max(0, p.flowT - dt);
  p.wallFreshT = Math.max(0, p.wallFreshT - dt);
  p.coyote = Math.max(0, p.coyote - dt);

  const left = isLeft(), right = isRight();
  const dir = (right ? 1 : 0) - (left ? 1 : 0);
  if (dir) p.face = dir;

  if (isJumpDown()) p.jumpBuf = JUMP_BUFFER;
  else p.jumpBuf = Math.max(0, p.jumpBuf - dt);

  if (isDashDown()) tryDash(dir);

  if (p.dashT > 0) {
    p.vx = p.dashDir * DASH_SPEED;
    p.vy = 0;
    ghostAcc += dt;
    if (ghostAcc > 0.032) {
      ghostAcc = 0;
      ghosts.push({ x: p.x, y: p.y, life: 1, rot: 0.25 * p.dashDir });
    }
  } else {
    // jump order: ground/coyote first, then wall
    if (p.jumpBuf > 0 && (p.grounded || p.coyote > 0)) {
      p.vy = JUMP_V;
      p.grounded = false;
      p.coyote = 0;
      p.jumpBuf = 0;
      p.wallJumps = 0;
      audio.play('jump');
      burst(p.x, p.y, 8, ['#e6c98e', '#a9774c', '#f5dfb0'], 4, { size: 1.5, life: 0.4, up: 1, type: 'dust' });
      ring(p.x, p.y, 'rgba(255,224,164,.5)', 1.4, 0.3);
    } else if (p.jumpBuf > 0 && p.wallDir !== 0 && !p.grounded) {
      const away = -p.wallDir;
      p.vx = away * WALL_JUMP_X;
      p.vy = WALL_JUMP_Y;
      p.face = away;
      p.grounded = false;
      p.coyote = 0;
      p.jumpBuf = 0;
      p.wallJumps++;
      p.wallFreshT = 1.5;
      audio.play('wall');
      const wvx = p.wallDir * 4;
      burst(p.x - p.wallDir * 0.35, p.y + 1.1, 10, ['#ffe0a0', '#9fe8c8', '#c84e3b'], 5, { size: 1.6, life: 0.46, up: 1 });
      addShake(1.5);
      if (p.wallJumps >= 3) {
        p.wallJumps = 0;
        p.flowT = FLOW_TIME;
        score += FLOW_BONUS;
        hitstop = Math.max(hitstop, HITSTOP_FLOW);
        addShake(5);
        flashT = Math.max(flashT, 0.12);
        audio.play('flow');
        ui.banner('流 · 蹬墙三连', `疾行加速 ${FLOW_TIME.toFixed(0)} 秒 · +${FLOW_BONUS} 分`, 1800);
        floatText(p.x, p.y + 2.2, `+${FLOW_BONUS}`, '#ffe58f');
        ring(p.x, p.y + 0.8, 'rgba(255,225,150,.9)', 2.5, 0.7);
        burst(p.x, p.y + 0.8, 18, ['#ffe8a8', '#9fe8c8'], 7, { size: 2.1, life: 0.7 });
      }
      if (!hintWall && runT < 12) {
        hintWall = true;
        ui.toast('漂亮的蹬墙！趁气未散按 Shift 冲刺', 2600);
      }
    }
    // horizontal control
    if (dir) {
      const target = dir * MOVE * (p.flowT > 0 ? FLOW_MULT : 1);
      p.vx = approach(p.vx, target, (p.grounded ? GROUND_ACC : AIR_ACC) * dt);
    } else {
      p.vx = approach(p.vx, 0, (p.grounded ? GROUND_FRICTION : AIR_DRAG) * dt);
    }
    // gravity and variable jump
    if (!p.grounded) {
      p.vy -= GRAV * dt;
      if (!isJumpHeld() && p.vy > 0) p.vy -= GRAV * 0.95 * dt;
      p.vy = Math.max(MAX_FALL, p.vy);
    } else if (p.vy < 0) {
      p.vy = 0;
    }
    // wall slide
    if (!p.grounded && p.wallDir !== 0 && p.vy < 0 && dir === p.wallDir) {
      p.vy = Math.max(p.vy, -WALL_SLIDE);
      if (Math.random() < dt * 26) {
        spawnParticle(p.x + p.wallDir * HALF_W, p.y + rnd(0.2, 1.4), -p.wallDir * rnd(0.5, 2.2), rnd(-2.5, -0.6), 'spark', '#e8c78d', rnd(0.2, 0.45), 1.1, { grav: 2 });
      }
    }
  }

  // integrate horizontal + wall collision
  p.x += p.vx * dt;
  p.x = clamp(p.x, HALF_W, WORLD_W - HALF_W);
  for (const w of level.walls) {
    if (p.x + HALF_W <= w.x || p.x - HALF_W >= w.x + w.w || p.y >= w.y + w.h || p.y + PH <= w.y) continue;
    if (p.vx > 0) p.x = w.x - HALF_W;
    else if (p.vx < 0) p.x = w.x + w.w + HALF_W;
    else {
      const dL = Math.abs(p.x - HALF_W - (w.x + w.w));
      const dR = Math.abs(p.x + HALF_W - w.x);
      if (dL < dR) p.x = w.x + w.w + HALF_W;
      else p.x = w.x - HALF_W;
    }
    p.vx = 0;
  }

  // integrate vertical + one-way landings
  const oldY = p.y;
  if (p.dashT <= 0) p.y += p.vy * dt;
  p.grounded = false;
  if (p.vy <= 0 || p.dashT <= 0) {
    let landY = -Infinity;
    for (const s of level.platforms) {
      if (p.x + HALF_W <= s.x + 0.01 || p.x - HALF_W >= s.x + s.w - 0.01) continue;
      if (oldY >= s.y - 0.015 && p.y <= s.y + 0.015 && s.y > landY) landY = s.y;
    }
    for (const w of level.walls) {
      const top = w.y + w.h;
      if (p.x + HALF_W <= w.x + 0.01 || p.x - HALF_W >= w.x + w.w - 0.01) continue;
      if (oldY >= top - 0.015 && p.y <= top + 0.015 && top > landY) landY = top;
    }
    if (landY > -Infinity) {
      p.y = landY;
      p.vy = 0;
      p.grounded = true;
    }
  }

  // wall probe after movement
  p.wallDir = 0;
  if (!p.grounded) {
    for (const w of level.walls) {
      if (p.y >= w.y + w.h || p.y + PH <= w.y) continue;
      if (Math.abs((p.x - HALF_W) - (w.x + w.w)) < 0.16 && p.x > w.x + w.w * 0.5) { p.wallDir = -1; break; }
      if (Math.abs((p.x + HALF_W) - w.x) < 0.16 && p.x < w.x + w.w * 0.5) { p.wallDir = 1; break; }
    }
  }

  if (p.grounded) {
    p.wallJumps = 0;
    p.coyote = COYOTE;
    if (!wasGrounded && prevVy < -7) {
      audio.play('land');
      burst(p.x, p.y, 6, ['#d8b27f', '#8c6a52'], 3, { size: 1.4, life: 0.35, type: 'dust', up: 0 });
      addShake(Math.min(2.5, -prevVy * 0.11));
    }
    if (Math.abs(p.vx) > 4 && Math.random() < dt * 12) {
      dustAcc += dt;
      if (dustAcc > 0.1) {
        dustAcc = 0;
        spawnParticle(p.x - p.face * 0.25, p.y + 0.05, -p.face * rnd(1, 3), rnd(0.2, 1.4), 'dust', 'rgba(214,174,122,.55)', rnd(0.25, 0.45), rnd(1, 2), { grav: -1 });
      }
    }
  }

  // trail
  trailAcc += dt;
  if (trailAcc > 0.035) {
    trailAcc = 0;
    p.trail.push({ x: p.x - p.face * 0.12, y: p.y + 1.42 });
    if (p.trail.length > 11) p.trail.shift();
  }

  // teach the first wall-dash inside the first ten seconds
  if (!hintDash && p.wallFreshT > 0 && runT < 10) {
    hintDash = true;
    ui.toast('趁蹬墙后的 1.5 秒按 Shift，疾影会额外加分', 2600);
  }
}

// --- interactions ---------------------------------------------------------
function updateHazards(dt) {
  for (const h of level.hazards) {
    if (h.static) { h.active = true; h.warn = false; continue; }
    const local = (runT + h.phase) % h.cycle;
    h.warn = local < h.warnDur;
    h.active = local >= h.warnDur && local < h.warnDur + h.activeDur;
  }
  if (player.invulnT > 0) return;
  for (const h of level.hazards) {
    if (!h.active) continue;
    if (player.x + HALF_W > h.x && player.x - HALF_W < h.x + h.w &&
      player.y < h.y + h.h && player.y + PH > h.y) {
      damage('刺阵');
      return;
    }
  }
}

function updatePickups() {
  const cx = player.x, cy = player.y + 0.86;
  for (const p of level.pickups) {
    if (p.taken) continue;
    const dx = cx - p.x, dy = cy - p.y;
    if (dx * dx + dy * dy < 0.82 * 0.82) {
      p.taken = true;
      dust++;
      chi = Math.min(MAX_CHI, chi + DUST_CHI);
      score += DUST_SCORE;
      audio.play('dust');
      burst(p.x, p.y, 12, ['#ffe7a6', '#f4bd62', '#fff5cf'], 5, { size: 1.8, life: 0.55, grav: -1 });
      ring(p.x, p.y, 'rgba(255,222,138,.75)', 1.2, 0.4);
      floatText(p.x, p.y + 0.7, `灯屑 +1 · 气 +${DUST_CHI}`, '#ffe7a6');
    }
  }
}

function checkProgress() {
  if (mode !== 'play') return;
  if (player.y > maxHeight) maxHeight = player.y;
  const fl = Math.floor(maxHeight);
  if (fl > lastScoredHeight) {
    score += (fl - lastScoredHeight) * HEIGHT_SCORE;
    lastScoredHeight = fl;
  }
  while (nextCpIndex <= CFG.CP_COUNT && player.y >= nextCpIndex * CFG.CP_STEP) {
    checkpointY = nextCpIndex * CFG.CP_STEP;
    cpSpawn = { x: 15, y: checkpointY + 0.03 };
    score += CP_BONUS;
    chi = MAX_CHI;
    nextCpIndex++;
    audio.play('checkpoint');
    addShake(2.5);
    flashT = Math.max(flashT, 0.1);
    ring(player.x, player.y + 0.8, 'rgba(151,240,207,.9)', 3, 0.8);
    burst(player.x, player.y + 0.8, 22, ['#b9f3d9', '#ffe2a1'], 7, { size: 2, life: 0.8 });
    ui.banner(`灯标 ${checkpointY}m`, `命火已记 · 气已回满 · +${CP_BONUS}`, 1900);
    report('progress', { score, progress: checkpointY });
    audio.setState(zoneNow().id);
  }
  if (player.y < checkpointY - 28) {
    damage('坠入深渊');
  }
  if (player.y >= WORLD_H) win();
}

// --- camera / fx ----------------------------------------------------------
function updateCamera(dt, snap = false) {
  const target = clamp(player.y - 17.8, -5, WORLD_H - 18);
  if (snap) cameraY = target;
  else cameraY += (target - cameraY) * (1 - Math.exp(-7.5 * dt));
  shakeAmp *= Math.exp(-6.2 * dt);
  if (shakeAmp < 0.04) shakeAmp = 0;
  flashT = Math.max(0, flashT - dt);
  if (hitstop > 0) hitstop = Math.max(0, hitstop - dt);
}

function updateFx(dt) {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.life -= dt;
    if (p.life <= 0) { particles.splice(i, 1); continue; }
    p.vy -= (p.grav || 0) * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.rot = (p.rot || 0) + dt * 5;
  }
  for (let i = floats.length - 1; i >= 0; i--) {
    const f = floats[i];
    f.life -= dt;
    f.y += dt * 1.15;
    if (f.life <= 0) floats.splice(i, 1);
  }
  for (let i = ghosts.length - 1; i >= 0; i--) {
    ghosts[i].life -= dt * 3.4;
    if (ghosts[i].life <= 0) ghosts.splice(i, 1);
  }
}

// --- main tick ------------------------------------------------------------
function tick(dt) {
  processMeta();
  if (mode !== 'play') { updateFx(dt); updateCamera(dt); clearPressed(); return; }
  if (paused) { updateFx(0); clearPressed(); return; }
  if (hitstop > 0) {
    hitstop = Math.max(0, hitstop - dt);
    updateFx(dt * 0.28);
    updateCamera(dt * 0.3);
    clearPressed();
    return;
  }
  runT += dt;
  checkProgress();
  if (mode !== 'play') { updateFx(dt); clearPressed(); return; }
  updatePlayer(dt);
  updatePickups();
  updateHazards(dt);
  if (mode === 'play') checkProgress();
  updateFx(dt);
  updateCamera(dt);
  if (mode === 'play') {
    const z = zoneNow();
    if (audio.state !== 'danger' && lives === 1) audio.setState('danger');
    else if (lives > 1 && audio.state === 'danger') audio.setState(z.id);
    else if (audio.state === 'title' || !audio.state) audio.setState(z.id);
  }
  clearPressed();
}

// --- render ---------------------------------------------------------------
let lastRenderT = 0;
function render(t) {
  lastRenderT = t;
  const zone = zoneNow();
  const z = zoneAt(clamp(player.y, 0, WORLD_H - 0.001));
  const shakeX = shakeAmp > 0 ? Math.sin(t * 88) * shakeAmp : 0;
  const shakeY = shakeAmp > 0 ? Math.cos(t * 73) * shakeAmp * 0.7 : 0;
  renderer.draw({
    t, mode, paused,
    cameraY, shakeX, shakeY,
    level, player, particles, floats, ghosts,
    checkpointY, flowT: player.flowT,
    flashT, runT,
    showPlayer: true,
  });
  ui.setHud({
    height: maxHeight,
    best,
    score: Math.floor(score),
    dust,
    lives,
    chi,
    maxChi: MAX_CHI,
    dashCd: player.dashCd,
    flowT: player.flowT,
    flowMult: player.flowT > 0 ? FLOW_MULT : 1,
    zone: z,
  });
}

// --- loop -----------------------------------------------------------------
let lastTs = performance.now();
let acc = 0;
function frame(ts) {
  requestAnimationFrame(frame);
  let dt = (ts - lastTs) / 1000;
  lastTs = ts;
  if (!Number.isFinite(dt) || dt < 0) dt = 0;
  dt = Math.min(dt, 0.05);
  if (!document.hidden) {
    if (mode === 'play' && !paused && !noAuto) {
      acc = Math.min(acc + dt, 0.16);
      let guard = 0;
      while (acc >= DT && guard++ < 6) { tick(DT); acc -= DT; }
    } else {
      processMeta();
      ambientT += dt;
      if (!paused) updateFx(dt);
      updateCamera(dt);
    }
  }
  audio.tick(dt);
  render(ts / 1000);
}

// --- boot -----------------------------------------------------------------
resetRun();
mode = 'title';
snapCamera();
ui.setBest(best);
loadMutedUI();
ui.showTitle(true);
ui.setHud({
  height: maxHeight, best, score, dust, lives, chi, maxChi: MAX_CHI,
  dashCd: 0, flowT: 0, flowMult: 1, zone: zoneAt(0),
});
audio.setState('title');
render(performance.now() / 1000);
requestAnimationFrame(frame);

if (AUTOSTART && !AUTOTEST) {
  startGame();
}

// --- G debug hooks --------------------------------------------------------
function stateSnapshot() {
  return {
    mode, paused, noAuto,
    x: player.x, y: player.y, height: player.y, maxHeight,
    vx: player.vx, vy: player.vy, face: player.face,
    grounded: player.grounded, wallDir: player.wallDir, wallJumps: player.wallJumps,
    flowT: player.flowT, flowMult: player.flowT > 0 ? FLOW_MULT : 1,
    wallFreshT: player.wallFreshT,
    dashT: player.dashT, dashCd: player.dashCd, invuln: player.invulnT,
    lives, score: Math.floor(score), dust, chi, checkpoint: checkpointY,
    best, runT, streakBroken: player.wallJumps,
    particles: particles.length, floats: floats.length,
    pickupsLeft: level.pickups.reduce((n, p) => n + (p.taken ? 0 : 1), 0),
    zone: zoneNow().id, route: levelRoute,
  };
}

const G = {
  err: __BOOTERR,
  W, H, PPM, WORLD_W, WORLD_H,
  step: (n = 60, dt = DT) => {
    for (let i = 0; i < n; i++) { tick(dt); render(performance.now() / 1000); }
  },
  upd: (n = 30, dt = DT) => { for (let i = 0; i < n; i++) tick(dt); },
  press,
  release,
  setNoAuto: (v) => { noAuto = !!v; },
  setReportTarget: (fn) => { reportTarget = typeof fn === 'function' ? fn : null; },
  state: stateSnapshot,
  setHeight: (y) => {
    player.y = clamp(Number(y) || 0, -10, WORLD_H);
    player.vx = player.vy = 0;
    player.grounded = false; player.coyote = 0; player.wallDir = 0;
    player.dashT = 0; player.dashCd = 0; player.trail.length = 0;
    snapCamera();
    return player.y;
  },
  setPos: (x, y) => {
    player.x = clamp(Number(x) || 0, HALF_W, WORLD_W - HALF_W);
    player.y = clamp(Number(y) || 0, -10, WORLD_H);
    player.vx = player.vy = 0;
    player.grounded = false; player.coyote = 0; player.wallDir = 0;
    player.dashT = 0; player.trail.length = 0;
    snapCamera();
    return { x: player.x, y: player.y };
  },
  setLives: (n) => { lives = clamp(n | 0, 0, 9); ui.setHud({ height: maxHeight, best, score, dust, lives, chi, maxChi: MAX_CHI, dashCd: player.dashCd, flowT: player.flowT, flowMult: player.flowT > 0 ? FLOW_MULT : 1, zone: zoneNow() }); },
  setChi: (n) => { chi = clamp(Number(n) || 0, 0, MAX_CHI); },
  setScore: (n) => { score = Math.max(0, Number(n) || 0); },
  setDust: (n) => { dust = Math.max(0, n | 0); },
  setBest: (n) => { best = Math.max(0, n | 0); ui.setBest(best); },
  setInvuln: (n) => { player.invulnT = Math.max(0, Number(n) || 0); },
  setPaused: (v) => { if (mode === 'play') { paused = !!v; ui.setPaused(paused); } },
  forceGameOver: () => { if (mode !== 'play') startGame(); lives = 0; gameOver('力竭'); },
  forceWin: () => { if (mode !== 'play') startGame(); win(); },
  damage: (cause) => damage(cause || '试炼'),
  startGame, toTitle, win, gameOver, report,
  level, route: levelRoute, audio, ui, renderer,
  audioState: () => audio.state,
  render: () => render(performance.now() / 1000),
};
window.G = G;
window.__G = G;

// --- autotest -------------------------------------------------------------
const nap = () => new Promise(r => {
  const mc = new MessageChannel();
  mc.port1.onmessage = () => r();
  mc.port2.postMessage(0);
});

const finite = v => typeof v === 'number' && Number.isFinite(v);

async function autotest() {
  G.setNoAuto(true);
  const results = [];
  const assert = (id, ok, name) => {
    results.push({ id, ok: !!ok, name });
    if (!ok) console.warn(`[autotest] FAIL T${id}: ${name}`);
  };
  const S = () => G.state();
  const savedBest = best;
  const savedStored = (() => { try { return localStorage.getItem('ssn.best'); } catch (e) { return null; } })();
  const frames = [];
  G.setReportTarget(f => frames.push(f));
  audio.setMuted(true, false);

  try {
    await nap();

    // T1 boot clean
    assert(1, G.err.length === 0 && (!window.__BOOTERR || window.__BOOTERR.length === 0), `启动零报错 errors=${G.err.length}`);

    // T2 short run stays finite
    startGame();
    G.press('KeyD', 'Space'); G.upd(20); G.release('KeyD', 'Space'); G.upd(60);
    const st2 = S();
    assert(2, ['x', 'y', 'vx', 'vy', 'height', 'score', 'chi', 'dashCd'].every(k => finite(st2[k])), '跑动 80 帧关键数值无 NaN');

    // T3 ground jump impulse
    startGame();
    const yj = S().height;
    G.press('Space'); G.upd(1); G.release('Space');
    assert(3, S().vy > 10 && S().height > yj, `跳跃上升 vy=${S().vy.toFixed(2)}`);

    // T4 wall-jump maths (real wall contact)
    startGame();
    G.setPos(1.58, 5.2); G.upd(1);
    const wallDetected = S().wallDir === -1;
    G.press('Space'); G.upd(1); G.release('Space');
    const st4 = S();
    assert(4, wallDetected && st4.vx > 5 && st4.vy > 10 && st4.wallJumps >= 1, `贴墙=${wallDetected} vx=${st4.vx.toFixed(1)} vy=${st4.vy.toFixed(1)} 连跳=${st4.wallJumps}`);

    // T5 dash cost / i-frames / cooldown
    startGame();
    G.setChi(100);
    G.press('KeyD', 'ShiftLeft'); G.upd(1); G.release('ShiftLeft', 'KeyD');
    const st5 = S();
    assert(5, st5.chi === 76 && st5.dashCd > 0.2 && st5.invuln > 0, `气 100→${st5.chi} cd=${st5.dashCd.toFixed(2)} i帧=${st5.invuln.toFixed(2)}`);

    // T6 dash rejection during cooldown
    G.press('ShiftLeft'); G.upd(1); G.release('ShiftLeft');
    assert(6, S().chi === 76, '冷却中的第二次冲刺不扣气');

    // T7 dash refusal when out of chi
    G.setChi(10); G.upd(36);
    G.press('ShiftLeft'); G.upd(1); G.release('ShiftLeft');
    assert(7, S().chi === 10 && S().dashT === 0, '气不足时冲刺被拒绝');

    // T8 three air wall-jumps → flow boost and score
    startGame();
    for (let i = 0; i < 3; i++) {
      G.setPos(i % 2 === 0 ? 1.58 : 28.42, 5.2 + i * 0.15);
      G.upd(1);
      G.press('Space'); G.upd(1); G.release('Space'); G.upd(1);
    }
    const st8 = S();
    assert(8, st8.flowT > 0 && st8.score >= FLOW_BONUS, `三连蹬墙 flowT=${st8.flowT.toFixed(2)} score=${st8.score}`);

    // T9 wall-jump + dash bonus (first ten seconds positive loop)
    startGame();
    G.setPos(1.58, 5.2); G.upd(1);
    G.press('Space'); G.upd(1); G.release('Space'); G.upd(1);
    const scoreBeforeDash = S().score;
    G.press('ShiftLeft'); G.upd(1); G.release('ShiftLeft');
    assert(9, S().score >= scoreBeforeDash + 100, `蹬墙后冲刺 +${S().score - scoreBeforeDash} 分`);

    // T10 checkpoint activation
    startGame();
    frames.length = 0;
    G.setHeight(150); G.upd(1);
    const st10 = S();
    assert(10, st10.checkpoint >= 150 && st10.chi === MAX_CHI && st10.score >= CP_BONUS, `灯标=${st10.checkpoint}m 气=${st10.chi} 分=${st10.score}`);

    // T11 progress report exists after checkpoint
    assert(11, frames.some(f => f.kind === 'progress' && f.progress >= 150), `progress 帧=${frames.map(f => f.kind).join(',')}`);

    // T12 damage costs a life and respawns at checkpoint
    G.setLives(3); G.setInvuln(0);
    const cp10 = S().checkpoint;
    G.damage('刺阵'); G.upd(2);
    const st12 = S();
    assert(12, st12.lives === 2 && st12.mode === 'play' && Math.abs(st12.y - cp10) < 2.5, `命 3→${st12.lives} 复活=${st12.y.toFixed(1)}m`);

    // T13 failure path: final life → gameOver report
    frames.length = 0;
    G.setInvuln(0); G.setLives(1);
    G.damage('最后一击'); G.upd(1);
    assert(13, S().mode === 'over' && frames.some(f => f.kind === 'gameOver'), `mode=${S().mode} 上报=${frames.map(f => f.kind).join(',')}`);

    // T14 victory path: crossing the summit reaches complete
    startGame(); frames.length = 0;
    G.setHeight(1200); G.upd(1);
    assert(14, S().mode === 'win' && frames.some(f => f.kind === 'complete' && f.progress === 1200), `mode=${S().mode} 上报=${frames.map(f => f.kind).join(',')}`);

    // T15 dust pickup economy
    startGame();
    const pk = level.pickups.find(p => !p.taken);
    G.setChi(40); G.setDust(0); G.setScore(0);
    G.setPos(pk.x, pk.y - 0.72); G.upd(1);
    const st15 = S();
    assert(15, st15.dust === 1 && st15.chi === 58 && st15.score >= DUST_SCORE, `灯屑=${st15.dust} 气=${st15.chi} 分=${st15.score}`);

    // T16 height pays score
    startGame();
    const s16 = S().score;
    G.setHeight(20); G.upd(1);
    assert(16, S().score > s16 + 20, `爬升加分 ${s16}→${S().score}`);

    // T17 simulated input moves the body
    startGame();
    const x17 = S().x;
    G.press('KeyD'); G.upd(30); G.release('KeyD');
    assert(17, S().x > x17 + 1, `按 D 30 帧 x ${x17.toFixed(2)}→${S().x.toFixed(2)}`);

    // T18 jump input raises height
    startGame();
    const h18 = S().height;
    G.press('Space'); G.upd(12); G.release('Space');
    assert(18, S().height > h18 + 0.7, `空格后高度 ${h18.toFixed(2)}→${S().height.toFixed(2)}`);

    // T19 pause freezes, resume moves
    startGame();
    G.press('KeyD'); G.upd(6);
    G.press('KeyP'); G.upd(1);
    const xPause = S().x;
    G.upd(30);
    const pausedX = S().x;
    G.press('KeyP'); G.upd(1); G.upd(10); G.release('KeyD');
    assert(19, S().paused === false && Math.abs(pausedX - xPause) < 0.001 && S().x > pausedX + 0.2, `暂停冻结 x=${pausedX.toFixed(2)} 恢复后=${S().x.toFixed(2)}`);

    // T20 touch bindings exist and jump button works
    startGame();
    const h20 = S().height;
    const touchIds = ['btn-left', 'btn-right', 'btn-jump', 'btn-dash'];
    const touchOk = touchIds.every(id => !!document.getElementById(id));
    const jumpBtn = document.getElementById('btn-jump');
    jumpBtn.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerType: 'touch' }));
    G.upd(2);
    jumpBtn.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, pointerType: 'touch' }));
    assert(20, touchOk && S().height > h20, `触控键=${touchOk} 跳后高度=${S().height.toFixed(2)}`);

    // T21 restart resets the run
    startGame();
    G.setScore(999); G.setDust(5); G.setHeight(300); G.forceGameOver();
    startGame();
    const st21 = S();
    assert(21, st21.lives === 3 && st21.score === 0 && st21.dust === 0 && st21.mode === 'play' && st21.height < 5, `重开 lives=${st21.lives} score=${st21.score} h=${st21.height.toFixed(1)}`);

    // T22 best height persists and can be restored
    try { localStorage.setItem('ssn.best', '0'); } catch (e) { }
    G.setBest(0);
    startGame(); G.setHeight(432); G.upd(1); G.forceGameOver();
    let stored = 0;
    try { stored = parseInt(localStorage.getItem('ssn.best') || '0', 10) || 0; } catch (e) { }
    assert(22, stored >= 432 && S().best >= 432, `localStorage=${stored} state.best=${S().best}`);

    // T23 ready is the first report frame
    assert(23, reports[0] && reports[0].kind === 'ready', `首帧=${reports[0] && reports[0].kind}`);

    // T24 progress → gameOver order
    startGame(); frames.length = 0;
    G.setHeight(150); G.upd(1); G.forceGameOver();
    const kinds24 = frames.map(f => f.kind);
    assert(24, kinds24.indexOf('progress') >= 0 && kinds24.indexOf('progress') < kinds24.indexOf('gameOver') && kinds24[kinds24.length - 1] === 'gameOver', `帧序=${kinds24.join('→')}`);

    // T25 progress → complete order and integer payload
    startGame(); frames.length = 0;
    G.setHeight(1200); G.upd(1);
    const kinds25 = frames.map(f => f.kind);
    const last25 = frames[frames.length - 1];
    assert(25, kinds25.includes('complete') && Number.isInteger(last25.score) && Number.isInteger(last25.progress), `帧序=${kinds25.join('→')}`);

    // T26 level route continuity
    assert(26, levelRoute.count > 350 && levelRoute.maxDy <= 3.05 && levelRoute.maxEdgeGap <= 7.0 && levelRoute.top >= 1199, `路线 ${levelRoute.count} 台 最大升差 ${levelRoute.maxDy.toFixed(2)}m 最大横距 ${levelRoute.maxEdgeGap.toFixed(2)}m`);

    // T27 full fast-forward with random input, no NaN / new errors
    startGame();
    const errBefore = G.err.length;
    const codes = ['KeyA', 'KeyD', 'Space', 'ShiftLeft', 'Space'];
    for (let i = 0; i < 1200; i++) {
      if (i % 23 === 0) G.release('KeyA', 'KeyD', 'ShiftLeft');
      if (i % 31 === 0) G.press(codes[(i / 31 | 0) % codes.length]);
      G.upd(1);
    }
    G.release('KeyA', 'KeyD', 'Space', 'ShiftLeft');
    const st27 = S();
    const finite27 = Object.values(st27).filter(v => typeof v === 'number').every(Number.isFinite);
    assert(27, finite27 && G.err.length === errBefore, `1200 帧快进 finite=${finite27} err+${G.err.length - errBefore}`);

    // T28 render path advances without errors
    const errBefore28 = G.err.length;
    G.step(8);
    assert(28, G.err.length === errBefore28, 'step 渲染 8 帧零新增错误');

    // T29 muted by default in autotest
    assert(29, audio.muted === true, '自测默认静音');

    // T30 static bridge aliases
    assert(30, typeof window.goHome === 'function' && typeof window.clickMore === 'function' && typeof window.dp_share === 'function' && typeof window.play68_init === 'function', 'play68 桥接别名存在');

    // T31 title screen has best + series imprint + one-line how-to
    toTitle();
    const titleTxt = document.getElementById('title').textContent || '';
    const bestTxt = document.getElementById('titlebest').textContent || '';
    assert(31, /灯匠夜游/.test(titleTxt) && /2/.test(titleTxt) && /最高|尚无/.test(bestTxt), `标题 best="${bestTxt}"`);

    // T32 back to title and no active run
    assert(32, S().mode === 'title' && !document.getElementById('title').classList.contains('hide'), `mode=${S().mode}`);

    // restore the player's own best record after all destructive tests
    try {
      if (savedStored == null) localStorage.removeItem('ssn.best');
      else localStorage.setItem('ssn.best', savedStored);
    } catch (e) { }
    G.setBest(savedBest);
    audio.setMuted(true, false);
    ui.setMuted(true);
    G.setReportTarget(null);
  } catch (err) {
    window.__TEST_ERR = String(err && err.stack || err);
    console.error('[autotest] crashed:', window.__TEST_ERR);
    const pass = results.filter(r => r.ok).length;
    window.__TEST = { pass, fail: results.length - pass + 1, total: results.length + 1, passed: pass, failed: results.length - pass + 1, results, done: true, crashed: true };
    return;
  }

  const pass = results.filter(r => r.ok).length;
  const fail = results.length - pass;
  window.__TEST = {
    pass, fail, total: results.length,
    passed: pass, failed: fail,
    results, done: true,
  };
  console.log(`[autotest] ${pass}/${results.length} passed`);
}

if (AUTOTEST) autotest();

